export function getFrozenExpectedObjectProbeDescriptors(file) {
  const descriptors = FROZEN_EXPECTED_OBJECT_PROBE_DESCRIPTORS[file];
  if (!Array.isArray(descriptors) || descriptors.length === 0) {
    throw new Error(`HOLD: no frozen object-probe descriptors for ${file}`);
  }
  const expressions = TARGET_OBJECT_PROBES[file] || [];
  if (expressions.length !== descriptors.length) {
    throw new Error(`HOLD: frozen object-probe descriptors do not pair with TARGET_OBJECT_PROBES for ${file}`);
  }
  return structuredClone(descriptors);
}

export function assertExpectedObjectProbeDescriptorsImmutable(file) {
  const live = FROZEN_EXPECTED_OBJECT_PROBE_DESCRIPTORS[file];
  if (!live) {
    throw new Error(`HOLD: no frozen object-probe descriptors for ${file}`);
  }
  const clone = getFrozenExpectedObjectProbeDescriptors(file);
  if (JSON.stringify(live) !== JSON.stringify(clone)) {
    throw new Error(`HOLD: frozen object-probe descriptors mutated for ${file}`);
  }
  return { file, unchanged: true, count: live.length };
}

function classifyObjectProbeExpression(expression) {
  const text = String(expression || "").trim();
  const match = text.match(OBJECT_PROBE_RESOLVER_RE);
  if (!match) return null;
  return { resolver: match[1], lookup: match[2], expression: text };
}

function objectProbeSelectSql(expression) {
  const classified = classifyObjectProbeExpression(expression);
  if (!classified) {
    throw new Error(`HOLD: malformed object-probe expression: ${expression}`);
  }
  const resolver = classified.expression;
  if (classified.resolver === "to_regprocedure") {
    return `(
      SELECT jsonb_build_object(
        'object_type', 'routine'::text,
        'schema', n.nspname,
        'object_name', p.proname,
        'prokind', p.prokind::text,
        'identity_arguments', pg_get_function_identity_arguments(p.oid)
      )
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE p.oid = ${resolver}
    )`;
  }
  if (classified.resolver === "to_regclass") {
    return `(
      SELECT jsonb_build_object(
        'object_type', 'class'::text,
        'schema', n.nspname,
        'object_name', c.relname,
        'prokind', ''::text,
        'identity_arguments', ''::text
      )
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE c.oid = ${resolver}
    )`;
  }
  if (classified.resolver === "to_regtype") {
    return `(
      SELECT jsonb_build_object(
        'object_type', 'type'::text,
        'schema', n.nspname,
        'object_name', t.typname,
        'prokind', ''::text,
        'identity_arguments', ''::text
      )
      FROM pg_type t
      JOIN pg_namespace n ON n.oid = t.typnamespace
      WHERE t.oid = ${resolver}
    )`;
  }
  return `(
    SELECT jsonb_build_object(
      'object_type', 'namespace'::text,
      'schema', n.nspname,
      'object_name', n.nspname,
      'prokind', ''::text,
      'identity_arguments', ''::text
    )
    FROM pg_namespace n
    WHERE n.oid = ${resolver}
  )`;
}

/**
 * Catalog-boundary object probe. to_regprocedure / to_regclass /
 * to_regtype / to_regnamespace resolve the intended object (must be
 * non-null). The OID is used only to join pg_proc+pg_namespace (or the
 * matching catalog). Output is structured identity fields — never
 * to_regprocedure(...)::text compared with lookup spelling, never OID
 * columns, never JS-rebuilt argument lists.
 */
export function objectProbeSql(expressions) {
  if (!Array.isArray(expressions) || expressions.length === 0) {
    throw new Error("HOLD: object probe expressions missing");
  }
  const selects = expressions.map((expr, i) => `${objectProbeSelectSql(expr)} AS p${i}`);
  return `SELECT\n  ${selects.join(",\n  ")};`;
}

function structuredObjectProbeIdentityExact(observed, expected) {
  if (!expected || typeof expected !== "object" || Array.isArray(expected)) {
    return { ok: false, reason: "expected probe descriptor missing" };
  }
  if (!observed || typeof observed !== "object" || Array.isArray(observed)) {
    return { ok: false, reason: "observed probe identity is not a structured object" };
  }
  const observedKeys = Object.keys(observed).sort();
  const expectedKeys = Object.keys(expected).sort();
  if (
    observedKeys.length !== OBJECT_PROBE_IDENTITY_KEYSET.length
    || observedKeys.some((key, i) => key !== OBJECT_PROBE_IDENTITY_KEYSET[i])
  ) {
    return { ok: false, reason: "observed probe identity keys are not the exact catalog field set" };
  }
  if (
    expectedKeys.length !== OBJECT_PROBE_IDENTITY_KEYSET.length
    || expectedKeys.some((key, i) => key !== OBJECT_PROBE_IDENTITY_KEYSET[i])
  ) {
    return { ok: false, reason: "expected probe descriptor keys are not the exact catalog field set" };
  }
  for (const key of OBJECT_PROBE_OID_KEYS) {
    if (Object.prototype.hasOwnProperty.call(observed, key)
      || Object.prototype.hasOwnProperty.call(expected, key)) {
      return { ok: false, reason: "probe identity must not include OID or catalog-number fields" };
    }
  }
  for (const field of OBJECT_PROBE_IDENTITY_FIELDS) {
    if (typeof observed[field] !== "string" || typeof expected[field] !== "string") {
      return { ok: false, reason: `probe identity field ${field} is not a string` };
    }
    if (observed[field] !== expected[field]) {
      return { ok: false, reason: `structured identity mismatch on ${field}` };
    }
  }
  return { ok: true };
}

function objectProbeIdentityFingerprint(identity) {
  return JSON.stringify(OBJECT_PROBE_IDENTITY_FIELDS.map((field) => identity[field]));
}

const ACL_PRIVILEGE_LETTERS = Object.freeze({
  a: "INSERT",
  r: "SELECT",
  w: "UPDATE",
  d: "DELETE",
  D: "TRUNCATE",
  x: "REFERENCES",
  t: "TRIGGER",
  X: "EXECUTE",
  U: "USAGE",
  C: "CREATE",
  c: "CONNECT",
  T: "TEMPORARY",
  m: "MAINTAIN",
  s: "SET",
});

function fingerprintCanonicalizationRejected(reason) {
  return Object.freeze({
    __f3_fingerprint_canonicalization_rejected: true,
    reason: String(reason || "canonicalization rejected"),
  });
}

function isFingerprintCanonicalizationRejected(value) {
  return Boolean(value && typeof value === "object" && value.__f3_fingerprint_canonicalization_rejected === true);
}

function compareCanonicalScalars(a, b) {
  if (a === b) return 0;
  const sa = a === null || a === undefined ? "" : typeof a === "boolean" ? (a ? "true" : "false") : String(a);
  const sb = b === null || b === undefined ? "" : typeof b === "boolean" ? (b ? "true" : "false") : String(b);
  if (sa < sb) return -1;
  if (sa > sb) return 1;
  return 0;
}

function compareRecordsByFields(a, b, fields) {
  for (const field of fields) {
    const cmp = compareCanonicalScalars(a?.[field], b?.[field]);
    if (cmp !== 0) return cmp;
  }
  return compareCanonicalScalars(JSON.stringify(a), JSON.stringify(b));
}

function recordsDeepEqual(a, b) {
  return JSON.stringify(a) === JSON.stringify(b);
}

function canonicalizeRoleSet(roles) {
  if (Array.isArray(roles)) {
    return [...roles].map((role) => String(role)).sort(compareCanonicalScalars);
  }
  if (typeof roles === "string") {
    const trimmed = roles.trim();
    if (trimmed.startsWith("{") && trimmed.endsWith("}")) {
      const body = trimmed.slice(1, -1);
      if (!body) return [];
      return body.split(",").map((part) => part.trim()).filter((part) => part.length > 0).sort(compareCanonicalScalars);
    }
    return trimmed ? [trimmed] : [];
  }
  if (roles == null) return [];
  return fingerprintCanonicalizationRejected("policy roles are not a set of names");
}

function splitSchemaIdentity(identity) {
  const text = String(identity);
  let depth = 0;
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === "(") depth += 1;
    else if (ch === ")") depth = Math.max(0, depth - 1);
    else if (ch === "." && depth === 0) {
      return { schema: text.slice(0, i), object_label: text.slice(i + 1) };
    }
  }
  return null;
}

function matchingParenClose(text, openIndex) {
  if (openIndex < 0 || text[openIndex] !== "(") return -1;
  let depth = 0;
  for (let j = openIndex; j < text.length; j += 1) {
    if (text[j] === "(") depth += 1;
    else if (text[j] === ")") {
      depth -= 1;
      if (depth === 0) return j;
    }
  }
  return -1;
}

/**
 * Offline upgrade of a frozen-contract object label into structured identity.
 * Extracts the whole identity_arguments slice between matching parentheses.
 * Never splits or reconstructs arguments on commas. Display labels are not
 * stored; callers must not parse a generated label back into fingerprint data.
 */
function structuredAclIdentityFromLegacyLabel(label) {
  const text = String(label);
  const open = text.indexOf("(");
  if (open < 0) {
    return {
      ok: true,
      object_type: "table",
      object_name: text,
      prokind: "",
      identity_arguments: "",
    };
  }
  const close = matchingParenClose(text, open);
  if (close < 0) {
    return { ok: false, reason: "acl routine identity arguments are unbalanced" };
  }
  if (close !== text.length - 1) {
    return { ok: false, reason: "acl routine identity has trailing identity junk" };
  }
  return {
    ok: true,
    object_type: "routine",
    object_name: text.slice(0, open),
    prokind: "f",
    identity_arguments: text.slice(open + 1, close),
  };
}

function parseLegacySchema(value) {
  if (value === "") return { ok: true, records: [] };
  const records = [];
  for (const part of String(value).split(",")) {
    const item = part.trim();
    if (!item) continue;
    const colon = item.indexOf(":");
    if (colon <= 0) return { ok: false, reason: "schema member is not schema:owner" };
    records.push({
      schema: item.slice(0, colon),
      owner: item.slice(colon + 1),
    });
  }
  return { ok: true, records };
}

function parseLegacyFunctionOwner(value) {
  const text = String(value);
  const records = [];
  let i = 0;
  while (i < text.length) {
    while (text[i] === ",") i += 1;
    if (i >= text.length) break;
    const ident = splitSchemaIdentity(text.slice(i));
    if (!ident || !ident.schema || !ident.object_label) {
      return { ok: false, reason: "function_owner identity is not schema.function(args)" };
    }
    const start = ident.object_label.indexOf("(");
    const close = matchingParenClose(ident.object_label, start);
    if (close < 0) return { ok: false, reason: "function_owner identity arguments are unbalanced" };
    const functionName = ident.object_label.slice(0, start);
    const identityArguments = ident.object_label.slice(start + 1, close);
    const consumedIdentity = ident.schema.length + 1 + close + 1;
    i += consumedIdentity;
    if (text[i] !== ":") return { ok: false, reason: "function_owner missing owner separator" };
    i += 1;
    const ownerEnd = text.indexOf(":", i);
    if (ownerEnd < 0) return { ok: false, reason: "function_owner missing security separator" };
    const owner = text.slice(i, ownerEnd);
    i = ownerEnd + 1;
    const secEnd = text.indexOf(":", i);
    if (secEnd < 0) return { ok: false, reason: "function_owner missing search_path separator" };
    const securityRaw = text.slice(i, secEnd);
    i = secEnd + 1;
    let brace = 0;
    const searchStart = i;
    while (i < text.length) {
      const ch = text[i];
      if (ch === "{") brace += 1;
      else if (ch === "}") brace = Math.max(0, brace - 1);
      else if (ch === "," && brace === 0) break;
      i += 1;
    }
    const searchPath = text.slice(searchStart, i);
    let securityDefiner = securityRaw;
    if (securityRaw === "true") securityDefiner = true;
    else if (securityRaw === "false") securityDefiner = false;
    records.push({
      schema: ident.schema,
      function: functionName,
      identity_arguments: identityArguments,
      owner,
      security_definer: securityDefiner,
      search_path: searchPath,
    });
  }
  return { ok: true, records };
}

function explodeAclPrivileges(privText) {
  const grants = [];
  const raw = String(privText || "");
  for (let i = 0; i < raw.length; i += 1) {
    const letter = raw[i];
    if (letter === "*") continue;
    const privilege = ACL_PRIVILEGE_LETTERS[letter] || letter;
    const grantable = raw[i + 1] === "*";
    if (grantable) i += 1;
    grants.push({ privilege, grantable });
  }
  return grants;
}

function parseLegacyAcl(value) {
  const text = String(value);
  const records = [];
  let i = 0;
  while (i < text.length) {
    while (text[i] === ",") i += 1;
    if (i >= text.length) break;
    const brace = text.indexOf("{", i);
    const emptySep = text.indexOf(":", i);
    let identity;
    let aclBody;
    if (brace >= 0 && (emptySep < 0 || brace <= emptySep || text[emptySep + 1] === "{")) {
      if (brace < i) return { ok: false, reason: "acl object missing privilege block" };
      identity = text.slice(i, brace);
      if (identity.endsWith(":")) identity = identity.slice(0, -1);
      let depth = 0;
      let j = brace;
      for (; j < text.length; j += 1) {
        if (text[j] === "{") depth += 1;
        else if (text[j] === "}") {
          depth -= 1;
          if (depth === 0) {
            j += 1;
            break;
          }
        }
      }
      aclBody = text.slice(brace + 1, j - 1);
      i = j;
    } else if (emptySep >= 0) {
      identity = text.slice(i, emptySep);
      aclBody = "";
      i = emptySep + 1;
    } else {
      return { ok: false, reason: "acl member is not identity:{grants}" };
    }
    const split = splitSchemaIdentity(identity);
    if (!split) return { ok: false, reason: "acl identity is not schema.object" };
    const structured = structuredAclIdentityFromLegacyLabel(split.object_label);
    if (!structured.ok) return { ok: false, reason: structured.reason };
    const identityFields = {
      object_type: structured.object_type,
      schema: split.schema,
      object_name: structured.object_name,
      prokind: structured.prokind,
      identity_arguments: structured.identity_arguments,
    };
    if (!aclBody) {
      records.push({
        ...identityFields,
        grantee: "",
        grantor: "",
        privilege: "",
        grantable: false,
      });
      continue;
    }
    for (const item of aclBody.split(",")) {
      const entry = item.trim();
      if (!entry) continue;
      const eq = entry.indexOf("=");
      const slash = entry.lastIndexOf("/");
      if (eq < 0 || slash < eq) return { ok: false, reason: "acl grant is not grantee=privs/grantor" };
      const granteeRaw = entry.slice(0, eq);
      const privs = entry.slice(eq + 1, slash);
      const grantor = entry.slice(slash + 1);
      const grantee = granteeRaw === "" ? "PUBLIC" : granteeRaw;
      const exploded = explodeAclPrivileges(privs);
      if (exploded.length === 0) {
        records.push({
          ...identityFields,
          grantee,
          grantor,
          privilege: "",
          grantable: false,
        });
        continue;
      }
      for (const grant of exploded) {
        records.push({
          ...identityFields,
          grantee,
          grantor,
          privilege: grant.privilege,
          grantable: grant.grantable,
        });
      }
    }
  }
  return { ok: true, records };
}

function parseLegacyPolicy(value) {
  const text = String(value);
  const records = [];
  let i = 0;
  const commands = ["SELECT", "INSERT", "UPDATE", "DELETE", "ALL"];
  while (i < text.length) {
    while (text[i] === ",") i += 1;
    if (i >= text.length) break;
    let commandIdx = -1;
    let command = null;
    for (const cmd of commands) {
      const needle = `:${cmd}:`;
      const found = text.indexOf(needle, i);
      if (found >= 0 && (commandIdx < 0 || found < commandIdx)) {
        commandIdx = found;
        command = cmd;
      }
    }
    if (commandIdx < 0 || !command) return { ok: false, reason: "policy missing command" };
    const identity = text.slice(i, commandIdx);
    const parts = identity.split(".");
    if (parts.length < 3) return { ok: false, reason: "policy identity is not schema.table.policy_name" };
    const schema = parts[0];
    const table = parts[1];
    const policyName = parts.slice(2).join(".");
    i = commandIdx + command.length + 2;
    if (text[i] !== "{") return { ok: false, reason: "policy missing roles" };
    const roleEnd = text.indexOf("}", i);
    if (roleEnd < 0) return { ok: false, reason: "policy roles are unbalanced" };
    const roles = canonicalizeRoleSet(text.slice(i, roleEnd + 1));
    if (isFingerprintCanonicalizationRejected(roles)) return { ok: false, reason: roles.reason };
    i = roleEnd + 1;
    if (text[i] !== ":") return { ok: false, reason: "policy missing using separator" };
    i += 1;
    let depth = 0;
    const usingStart = i;
    while (i < text.length) {
      const ch = text[i];
      if (ch === "(") depth += 1;
      else if (ch === ")") depth = Math.max(0, depth - 1);
      else if (ch === ":" && depth === 0 && text[i + 1] !== ":") break;
      if (ch === ":" && text[i + 1] === ":") {
        i += 2;
        continue;
      }
      i += 1;
    }
    const using = text.slice(usingStart, i);
    if (text[i] !== ":") return { ok: false, reason: "policy missing with_check separator" };
    i += 1;
    depth = 0;
    const checkStart = i;
    while (i < text.length) {
      const ch = text[i];
      if (ch === "(") depth += 1;
      else if (ch === ")") depth = Math.max(0, depth - 1);
      else if (ch === "," && depth === 0) break;
      i += 1;
    }
    records.push({
      schema,
      table,
      policy_name: policyName,
      command,
      permissive: true,
      roles,
      using,
      with_check: text.slice(checkStart, i),
    });
  }
  return { ok: true, records };
}

function parseLegacyCollection(key, value) {
  if (key === "schema") return parseLegacySchema(value);
  if (key === "function_owner") return parseLegacyFunctionOwner(value);
  if (key === "acl" || key === "acls") return parseLegacyAcl(value);
  if (key === "policy" || key === "policies") return parseLegacyPolicy(value);
  return { ok: false, reason: `${key} has no legacy parser` };
}

function normalizeRegistryRecord(key, raw, spec) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    return fingerprintCanonicalizationRejected(`${key} record is not an object`);
  }
  const out = {};
  for (const field of spec.fields) {
    if (Object.prototype.hasOwnProperty.call(raw, field)) {
      out[field] = raw[field];
    } else if (field === "permissive" && key === "policy") {
      out[field] = true;
    } else if (field === "roles" && key === "policy") {
      out[field] = [];
    } else if (field === "grantable" && key === "acl") {
      out[field] = false;
    } else if ((field === "identity_arguments" || field === "prokind" || field === "object_name") && key === "acl") {
      out[field] = "";
    } else if ((field === "security_definer" || field === "search_path") && key === "function_owner") {
      out[field] = field === "security_definer" ? null : "";
    } else {
      out[field] = null;
    }
  }
  for (const extra of Object.keys(raw).sort()) {
    if (!spec.fields.includes(extra)) out[extra] = raw[extra];
  }
  if (spec.innerSetFields.includes("roles")) {
    const roles = canonicalizeRoleSet(out.roles);
    if (isFingerprintCanonicalizationRejected(roles)) return roles;
    out.roles = roles;
  }
  if (spec.innerSetFields.includes("attacl")) {
    const tuples = out.attacl;
    if (tuples == null) {
      return fingerprintCanonicalizationRejected(`${key} attacl coverage missing`);
    }
    if (!Array.isArray(tuples)) {
      return fingerprintCanonicalizationRejected(`${key} attacl is not an array of tuples`);
    }
    const normalized = [];
    for (const tuple of tuples) {
      if (!tuple || typeof tuple !== "object" || Array.isArray(tuple)) {
        return fingerprintCanonicalizationRejected(`${key} attacl tuple is not an object`);
      }
      const grantor = tuple.grantor;
      const grantee = tuple.grantee;
      const privilege = tuple.privilege;
      const isGrantable = tuple.is_grantable;
      if (typeof grantor !== "string" || typeof grantee !== "string" || typeof privilege !== "string") {
        return fingerprintCanonicalizationRejected(`${key} attacl tuple is not structured grantor/grantee/privilege/is_grantable`);
      }
      if (typeof isGrantable !== "boolean") {
        return fingerprintCanonicalizationRejected(`${key} attacl is_grantable must be boolean`);
      }
      for (const extra of Object.keys(tuple)) {
        if (!["grantor", "grantee", "privilege", "is_grantable"].includes(extra)) {
          return fingerprintCanonicalizationRejected(`${key} attacl unexpected tuple field ${extra}`);
        }
      }
      normalized.push({
        grantor,
        grantee,
        privilege,
        is_grantable: isGrantable,
      });
    }
    const sorted = [...normalized].sort((a, b) => compareRecordsByFields(
      a,
      b,
      ["grantor", "grantee", "privilege", "is_grantable"],
    ));
    for (let i = 1; i < sorted.length; i += 1) {
      if (recordsDeepEqual(sorted[i - 1], sorted[i])) {
        return fingerprintCanonicalizationRejected(`${key} duplicate attacl tuples`);
      }
    }
    out.attacl = sorted;
    if (!Object.prototype.hasOwnProperty.call(out, "attacl_is_null") || typeof out.attacl_is_null !== "boolean") {
      return fingerprintCanonicalizationRejected(`${key} attacl_is_null missing or not boolean`);
    }
    if (out.attacl_is_null && out.attacl.length > 0) {
      return fingerprintCanonicalizationRejected(`${key} NULL attacl cannot carry grant tuples`);
    }
  }
  return out;
}

function canonicalizeRegisteredField(key, value) {
  const spec = FINGERPRINT_FIELD_REGISTRY[key];
  if (!spec) return value;
  if (spec.kind === "exact_string_set") {
    if (!Array.isArray(value)) return fingerprintCanonicalizationRejected(`${key} is not an array`);
    const items = [];
    for (const item of value) {
      if (typeof item !== "string") return fingerprintCanonicalizationRejected(`${key} member is not a string`);
      items.push(item);
    }
    const sorted = [...items].sort(compareCanonicalScalars);
    for (let i = 1; i < sorted.length; i += 1) {
      if (sorted[i] === sorted[i - 1]) {
        return fingerprintCanonicalizationRejected(`${key} duplicate records`);
      }
    }
    return sorted;
  }
  if (spec.kind === "record_set_or_exact_string" && typeof value === "string") {
    return value;
  }
  if (spec.kind === "record_set" || spec.kind === "record_set_or_exact_string") {
    let records;
    if (typeof value === "string") {
      const parsed = parseLegacyCollection(key, value);
      if (!parsed.ok) return fingerprintCanonicalizationRejected(parsed.reason);
      records = parsed.records.map((record) => normalizeRegistryRecord(key, record, spec));
    } else if (Array.isArray(value)) {
      records = value.map((record) => normalizeRegistryRecord(key, record, spec));
    } else {
      return fingerprintCanonicalizationRejected(`${key} must be a string or array of records`);
    }
    for (const record of records) {
      if (isFingerprintCanonicalizationRejected(record)) return record;
    }
    const sorted = [...records].sort((a, b) => compareRecordsByFields(a, b, spec.sortBy));
    for (let i = 1; i < sorted.length; i += 1) {
      if (recordsDeepEqual(sorted[i - 1], sorted[i])) {
        return fingerprintCanonicalizationRejected(`${key} duplicate records`);
      }
    }
    return sorted;
  }
  return value;
}

export function canonicalizeFingerprintForCompare(value, key = null) {
  if (key && FINGERPRINT_FIELD_REGISTRY[key]) {
    // Nested identity fields reuse names like `schema` / `name`. Those
    // scalars are not collections. Only canonicalize actual collections.
    if (typeof value === "string" && key === "schema" && !value.includes(":")) {
      // Nested identity fields reuse the name `schema` (e.g. "public").
      // Those scalars are not collections. Top-level schema inventory
      // always uses schema:owner and therefore contains ":".
      return value;
    }
    return canonicalizeRegisteredField(key, value);
  }
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) {
    return value.map((item) => canonicalizeFingerprintForCompare(item));
  }
  const out = {};
  for (const nextKey of Object.keys(value).sort()) {
    out[nextKey] = canonicalizeFingerprintForCompare(value[nextKey], nextKey);
    if (isFingerprintCanonicalizationRejected(out[nextKey])) return out[nextKey];
  }
  return out;
}

export function upgradeFingerprintToStructured(fingerprint) {
  const upgraded = canonicalizeFingerprintForCompare(fingerprint);
  if (isFingerprintCanonicalizationRejected(upgraded)) {
    throw new Error(`HOLD: fingerprint canonicalization rejected: ${upgraded.reason}`);
  }
  return upgraded;
}

function deepFreeze(value) {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) {
    for (const item of value) deepFreeze(item);
  } else {
    for (const key of Object.keys(value)) deepFreeze(value[key]);
  }
  return Object.freeze(value);
}

export const EVIDENCE_INDEX_FILENAME = "evidence-index.json";
export const EVIDENCE_INDEX_CHECKSUM_FILENAME = "evidence-index.sha256";
export const EXECUTABLE_MANIFEST_FILENAME = "executable-manifest.json";
export const EVIDENCE_INDEX_EXCLUSIONS = Object.freeze([
  EVIDENCE_INDEX_FILENAME,
  EVIDENCE_INDEX_CHECKSUM_FILENAME,
]);
export const YAML_ERROR_MARKER = "error: |-";

function sha256Utf8(text) {
  return createHash("sha256").update(String(text), "utf8").digest("hex");
}

function sha256Bytes(buf) {
  return createHash("sha256").update(buf).digest("hex");
}

export function sanitizeEvidenceOutBytes(raw, extraSecrets = []) {
  const secrets = extraSecrets.filter(Boolean).map(String);
  const input = Buffer.isBuffer(raw) ? raw : Buffer.from(String(raw ?? ""), "utf8");
  let text = input.toString("utf8");
  for (const secret of secrets) {
    if (!secret) continue;
    text = text.split(secret).join("[REDACTED]");
  }
  text = text.replace(
    /postgres(?:\.[A-Za-z0-9]+)?:[^@\s]+@/g,
    "postgres:[REDACTED]@",
  );
  return Buffer.from(text, "utf8");
}

export function extractExactPostgresError(text) {
  const blob = String(text || "");
  const lines = blob.split(/\r?\n/);
  const pgLines = lines
    .map((line) => line.trim())
    .filter((line) => /(?:^|[\s:])(?:ERROR|FATAL|PANIC):\s+\S/.test(line));
  if (pgLines.length > 0) {
    const chosen = pgLines[0].replace(/^\s*-\s*/, "").trim();
    if (chosen && chosen !== YAML_ERROR_MARKER && !/^error:\s*\|-?\s*$/.test(chosen)) {
      return chosen;
    }
  }
  for (let i = 0; i < lines.length; i += 1) {
    if (!/^error:\s*\|-?\s*$/.test(lines[i].trim())) continue;
    for (let j = i + 1; j < lines.length; j += 1) {
      const next = lines[j].replace(/^\s+/, "").trim();
      if (!next || next === YAML_ERROR_MARKER || /^error:\s*\|-?\s*$/.test(next)) continue;
      if (/^(code|name|stack|expected|actual|operator):\s*/.test(next)) break;
      if (/^(ERROR|FATAL|PANIC):/.test(next) || next.length > 0) {
        return next;
      }
    }
  }
  return null;
}

export function buildSuiteMetaFromSanitizedOut({ sanitizedOut, tests = [] } = {}) {
  const bytes = Buffer.isBuffer(sanitizedOut)
    ? sanitizedOut
    : Buffer.from(String(sanitizedOut ?? ""), "utf8");
  const text = bytes.toString("utf8");
  const listed = Array.isArray(tests) ? tests : [];
  return {
    sha256: sha256Bytes(bytes),
    bytes: bytes.byteLength,
    encoding: "utf8",
    sanitized_before_hash: true,
    tests: listed.map((test) => {
      const rawError = test?.exact_error ?? test?.error ?? test?.output ?? "";
      const exact = extractExactPostgresError(
        `${rawError}\n${test?.output || ""}\n${test?.stderr || ""}\n${text}`,
      );
      return {
        name: test?.name ?? null,
        ok: test?.ok ?? null,
        exact_error: exact,
      };
    }),
  };
}

export function writeSuiteMetaForOutFile(outPath, { tests = [], extraSecrets = [] } = {}) {
  const raw = fs.readFileSync(outPath);
  const sanitized = sanitizeEvidenceOutBytes(raw, extraSecrets);
  if (Buffer.compare(raw, sanitized) !== 0) {
    fs.writeFileSync(outPath, sanitized);
  }
  const meta = buildSuiteMetaFromSanitizedOut({ sanitizedOut: sanitized, tests });
  const metaPath = outPath.endsWith(".out")
    ? `${outPath.slice(0, -4)}.meta.json`
    : `${outPath}.meta.json`;
  fs.writeFileSync(metaPath, `${JSON.stringify(meta, null, 2)}\n`);
  return { metaPath, meta, sanitizedBytes: sanitized.byteLength };
}

export function buildEvidenceIndex({ artifacts = [], exclusions = EVIDENCE_INDEX_EXCLUSIONS } = {}) {
  const excluded = new Set(exclusions);
  const listed = [...artifacts]
    .map((item) => (typeof item === "string" ? { path: item } : item))
    .filter((item) => item && item.path && !excluded.has(path.basename(item.path)))
    .sort((a, b) => String(a.path).localeCompare(String(b.path)));
  return {
    version: 1,
    exclusions: [...excluded].sort(),
    self_hash: false,
    detached_checksum: EVIDENCE_INDEX_CHECKSUM_FILENAME,
    artifacts: listed,
  };
}

export const EXECUTABLE_BYTE_MANIFEST_FILENAME = "executable-byte-manifest.json";

export function buildExecutableManifest({ artifacts = [] } = {}) {
  const selfNames = new Set([
    EXECUTABLE_MANIFEST_FILENAME,
    EXECUTABLE_BYTE_MANIFEST_FILENAME,
  ]);
  const files = [...artifacts]
    .map((item) => (typeof item === "string" ? { path: item } : item))
    .filter((item) => item && item.path && !selfNames.has(path.basename(item.path)))
    .sort((a, b) => String(a.path).localeCompare(String(b.path)))
    .map((item) => ({
      path: item.path,
      sha256: item.sha256 || null,
      bytes: item.bytes ?? null,
    }));
  const selfEntries = files.filter((item) => selfNames.has(path.basename(item.path))).length;
  return {
    artifact: "executable-manifest",
    schema: "f3-executable-byte-manifest-v1",
    self_entries: selfEntries,
    files,
  };
}

export function assertExecutableManifestNoSelfEntry(manifest) {
  const files = Array.isArray(manifest?.files) ? manifest.files : [];
  const selfNames = new Set([EXECUTABLE_MANIFEST_FILENAME, EXECUTABLE_BYTE_MANIFEST_FILENAME]);
  const selfEntries = files.filter((item) => selfNames.has(path.basename(item?.path || item))).length;
  if (selfEntries !== 0 || manifest?.self_entries !== 0) {
    return { ok: false, reason: "HOLD: executable-byte-manifest contains a self-entry", self_entries: selfEntries };
  }
  return { ok: true, self_entries: 0 };
}

export function writeExecutableManifest(dir, artifacts = []) {
  const manifest = buildExecutableManifest({ artifacts });
  const selfCheck = assertExecutableManifestNoSelfEntry(manifest);
  if (!selfCheck.ok) {
    const err = new Error(selfCheck.reason);
    err.code = "F3_EXECUTABLE_MANIFEST_SELF_ENTRY";
    throw err;
  }
  const abs = path.join(dir, EXECUTABLE_MANIFEST_FILENAME);
  const body = `${JSON.stringify(manifest, null, 2)}\n`;
  fs.writeFileSync(abs, body);
  return {
    path: EXECUTABLE_MANIFEST_FILENAME,
    abs,
    sha256: sha256Utf8(body),
    bytes: Buffer.byteLength(body),
    manifest,
    self_entries: 0,
  };
}

export function writeEvidenceIndexAndChecksum(dir, artifacts = []) {
  const index = buildEvidenceIndex({ artifacts });
  const indexPath = path.join(dir, EVIDENCE_INDEX_FILENAME);
  const checksumPath = path.join(dir, EVIDENCE_INDEX_CHECKSUM_FILENAME);
  const body = `${JSON.stringify(index, null, 2)}\n`;
  fs.writeFileSync(indexPath, body);
  fs.writeFileSync(checksumPath, `${sha256Utf8(body)}\n`);
  return { indexPath, checksumPath, index, sha256: sha256Utf8(body) };
}

export function verifyEvidenceIndex(dir) {
  const indexPath = path.join(dir, EVIDENCE_INDEX_FILENAME);
  const checksumPath = path.join(dir, EVIDENCE_INDEX_CHECKSUM_FILENAME);
  if (!fs.existsSync(indexPath)) {
    return { ok: false, reason: "evidence-index.json missing" };
  }
  if (!fs.existsSync(checksumPath)) {
    return { ok: false, reason: "detached evidence-index.sha256 missing" };
  }
  const body = fs.readFileSync(indexPath, "utf8");
  const expected = fs.readFileSync(checksumPath, "utf8").trim();
  const actual = sha256Utf8(body);
  if (actual !== expected) {
    return { ok: false, reason: "evidence-index.sha256 does not match evidence-index.json" };
  }
  let parsed;
  try {
    parsed = JSON.parse(body);
  } catch {
    return { ok: false, reason: "evidence-index.json is not JSON" };
  }
  if (parsed.self_hash === true) {
    return { ok: false, reason: "evidence-index.json must not self-hash" };
  }
  const names = (parsed.artifacts || []).map((item) => path.basename(item.path || item));
  if (names.includes(EVIDENCE_INDEX_FILENAME) || names.includes(EVIDENCE_INDEX_CHECKSUM_FILENAME)) {
    return { ok: false, reason: "evidence-index lists itself or its detached checksum" };
  }
  const manifestAbs = path.join(dir, EXECUTABLE_MANIFEST_FILENAME);
  let manifestSelfEntries = 0;
  if (fs.existsSync(manifestAbs)) {
    try {
      const manifest = JSON.parse(fs.readFileSync(manifestAbs, "utf8"));
      const selfCheck = assertExecutableManifestNoSelfEntry(manifest);
      if (!selfCheck.ok) {
        return { ok: false, reason: selfCheck.reason, self_entries: selfCheck.self_entries };
      }
      manifestSelfEntries = selfCheck.self_entries;
    } catch {
      return { ok: false, reason: "executable-manifest.json is not JSON" };
    }
  }
  let hashMismatches = 0;
  let byteMismatches = 0;
  let missing = 0;
  let broken = 0;
  let redactedDigest = 0;
  for (const item of parsed.artifacts || []) {
    const rel = item.path || item;
    const artifactAbs = path.join(dir, rel);
    if (!fs.existsSync(artifactAbs)) {
      missing += 1;
      continue;
    }
    let committed;
    try {
      committed = fs.readFileSync(artifactAbs);
    } catch {
      broken += 1;
      continue;
    }
    const sha = sha256Bytes(committed);
    if (item.sha256 && item.sha256 !== sha) hashMismatches += 1;
    if (item.bytes != null && item.bytes !== committed.byteLength) byteMismatches += 1;
    if (/\[REDACTED\]/.test(committed.toString("utf8")) && /digest|sha256|privilege|identity_arguments/i.test(committed.toString("utf8"))) {
      if (/"digest[^"]*"\s*:\s*"[^"]*\[REDACTED\]/.test(committed.toString("utf8"))) redactedDigest += 1;
    }
  }
  const total = (parsed.artifacts || []).length;
  const verified = total - missing - broken - hashMismatches - byteMismatches;
  if (missing || broken || hashMismatches || byteMismatches || redactedDigest || manifestSelfEntries !== 0) {
    return {
      ok: false,
      reason: manifestSelfEntries !== 0
        ? "executable-byte-manifest contains a self-entry"
        : "evidence-index independent verify failed",
      verified,
      total,
      hashMismatches,
      byteMismatches,
      missing,
      broken,
      redactedDigest,
      self_entries: manifestSelfEntries,
      sha256: actual,
      index: parsed,
    };
  }
  return {
    ok: true,
    sha256: actual,
    index: parsed,
    verified,
    total,
    hashMismatches: 0,
    byteMismatches: 0,
    missing: 0,
    broken: 0,
    redactedDigest: 0,
    self_entries: 0,
  };
}

export function writeQualifyEvidenceArtifacts({ dest, sanitizedJson, extraSecrets = [] } = {}) {
  const abs = path.resolve(dest);
  if (fs.existsSync(abs) && fs.statSync(abs).isDirectory()) {
    const err = new Error("HOLD: --evidence-out must be a file path; directory rejected (EISDIR)");
    err.code = "EISDIR";
    throw err;
  }
  const sanitized = sanitizeEvidenceOutBytes(sanitizedJson, extraSecrets);
  const semantic = assertSanitizationPreservesSemanticFingerprint(sanitizedJson, sanitized);
  if (!semantic.ok) {
    const err = new Error(semantic.reason);
    err.code = "F3_EVIDENCE_SEMANTIC_SANITIZE";
    throw err;
  }
  fs.mkdirSync(path.dirname(abs), { recursive: true });
  fs.writeFileSync(abs, sanitized);
  const meta = writeSuiteMetaForOutFile(abs, {
    tests: [{
      name: "qualify-f3-db-push-disposable",
      ok: null,
      output: sanitized.toString("utf8"),
    }],
    extraSecrets,
  });
  const committed = fs.readFileSync(abs);
  if (Buffer.compare(committed, sanitized) !== 0) {
    fs.writeFileSync(abs, sanitized);
  }
  const regenerated = buildSuiteMetaFromSanitizedOut({
    sanitizedOut: fs.readFileSync(abs),
    tests: [{
      name: "qualify-f3-db-push-disposable",
      ok: null,
      output: fs.readFileSync(abs, "utf8"),
    }],
  });
  if (regenerated.sha256 !== meta.meta.sha256 || regenerated.bytes !== meta.meta.bytes) {
    fs.writeFileSync(meta.metaPath, `${JSON.stringify(regenerated, null, 2)}\n`);
    meta.meta = regenerated;
  }
  const verify = verifyCommittedSuiteEvidence({ outPath: abs, metaPath: meta.metaPath });
  if (!verify.ok) {
    const err = new Error(verify.reason);
    err.code = "F3_SUITE_EVIDENCE_INTEGRITY";
    throw err;
  }
  const dir = path.dirname(abs);
  const finalizedArtifacts = [
    { path: path.basename(abs), sha256: sha256Bytes(fs.readFileSync(abs)), bytes: fs.readFileSync(abs).byteLength },
    { path: path.basename(meta.metaPath), sha256: sha256Utf8(fs.readFileSync(meta.metaPath, "utf8")), bytes: fs.readFileSync(meta.metaPath).byteLength },
  ];
  const executable = writeExecutableManifest(dir, finalizedArtifacts);
  finalizedArtifacts.push({
    path: executable.path,
    sha256: executable.sha256,
    bytes: executable.bytes,
  });
  const index = writeEvidenceIndexAndChecksum(dir, finalizedArtifacts);
  const independent = verifyEvidenceIndex(dir);
  if (!independent.ok) {
    const err = new Error(independent.reason || "HOLD: evidence index independent verify failed");
    err.code = "F3_EVIDENCE_INDEX_VERIFY";
    throw err;
  }
  const committedManifest = fs.readFileSync(executable.abs);
  const committedManifestSha = sha256Bytes(committedManifest);
  const indexedManifest = (index.index.artifacts || []).find((item) => item.path === EXECUTABLE_MANIFEST_FILENAME);
  if (!indexedManifest || indexedManifest.sha256 !== committedManifestSha || indexedManifest.sha256 !== executable.sha256) {
    const err = new Error("HOLD: index executable-manifest hash != committed file");
    err.code = "F3_EXECUTABLE_MANIFEST_MISMATCH";
    throw err;
  }
  return { outPath: abs, ...meta, ...index, executable };
}

export const EVIDENCE_OUT_FILE_CONTRACT =
  "HOLD: --evidence-out must name a file path; a directory is rejected before any database access";

export const EVIDENCE_WRITE_HOLD =
  "HOLD: evidence-out write failed after database work; PASS is forbidden; process must exit nonzero";

/**
 * File-path-only --evidence-out contract. A directory is EISDIR and must
 * be rejected before Phase A / any database access.
 */
export function assertEvidenceOutFileContract(dest) {
  if (dest == null || dest === "") {
    return { ok: true, dest: null, dbAccess: false };
  }
  const abs = path.resolve(dest);
  let exists = false;
  let isDir = false;
  try {
    exists = fs.existsSync(abs);
    isDir = exists && fs.statSync(abs).isDirectory();
  } catch (err) {
    return {
      ok: false,
      dest: abs,
      dbAccess: false,
      code: err?.code || "F3_EVIDENCE_OUT_STAT",
      reason: `${EVIDENCE_OUT_FILE_CONTRACT}: ${err?.message || err}`,
    };
  }
  if (isDir) {
    return {
      ok: false,
      dest: abs,
      dbAccess: false,
      code: "EISDIR",
      reason: EVIDENCE_OUT_FILE_CONTRACT,
      dbPushCalls: 0,
      repairCalls: 0,
      continuationCalls: 0,
    };
  }
  return { ok: true, dest: abs, dbAccess: false, existed: exists };
}

export function verifyCommittedSuiteEvidence({ outPath, metaPath } = {}) {
  if (!outPath || !fs.existsSync(outPath)) {
    return {
      ok: false,
      reason: "HOLD: missing suite output referenced by committed evidence",
      code: "F3_SUITE_OUTPUT_MISSING",
    };
  }
  if (fs.statSync(outPath).isDirectory()) {
    return { ok: false, reason: EVIDENCE_OUT_FILE_CONTRACT, code: "EISDIR" };
  }
  if (!metaPath || !fs.existsSync(metaPath)) {
    return {
      ok: false,
      reason: "HOLD: missing suite metadata for committed output",
      code: "F3_SUITE_META_MISSING",
    };
  }
  const raw = fs.readFileSync(outPath);
  const sanitized = sanitizeEvidenceOutBytes(raw);
  if (Buffer.compare(raw, sanitized) !== 0) {
    return {
      ok: false,
      reason: "HOLD: committed suite output was not sanitized before metadata hashing",
      code: "F3_SUITE_NOT_SANITIZED",
    };
  }
  let meta;
  try {
    meta = JSON.parse(fs.readFileSync(metaPath, "utf8"));
  } catch {
    return { ok: false, reason: "HOLD: suite metadata is not JSON", code: "F3_SUITE_META_JSON" };
  }
  const actualSha = sha256Bytes(sanitized);
  const actualBytes = sanitized.byteLength;
  if (meta.sha256 !== actualSha || meta.bytes !== actualBytes) {
    return {
      ok: false,
      reason: "HOLD: suite output vs metadata SHA/byte-length disagreement",
      code: "F3_SUITE_META_MISMATCH",
      expected: { sha256: meta.sha256, bytes: meta.bytes },
      actual: { sha256: actualSha, bytes: actualBytes },
    };
  }
  return { ok: true, sha256: actualSha, bytes: actualBytes, meta };
}

export function assertSanitizationPreservesSemanticFingerprint(raw, sanitized = null) {
  const input = Buffer.isBuffer(raw) ? raw.toString("utf8") : String(raw ?? "");
  const outBuf = sanitized == null ? sanitizeEvidenceOutBytes(input) : sanitized;
  const output = Buffer.isBuffer(outBuf) ? outBuf.toString("utf8") : String(outBuf);
  const redactRe = /\[REDACTED\]/;
  const tryParse = (text) => {
    try { return JSON.parse(text); } catch { return null; }
  };
  const parsed = tryParse(output) || tryParse(input);
  if (parsed && typeof parsed === "object") {
    const semanticBlobs = [];
    const visit = (value, trail) => {
      if (value == null) return;
      if (typeof value === "string") {
        if (/acl|fingerprint|privilege|policy|identity/i.test(trail) && redactRe.test(value)) {
          semanticBlobs.push(trail);
        }
        return;
      }
      if (Array.isArray(value)) {
        value.forEach((item, i) => visit(item, `${trail}[${i}]`));
        return;
      }
      if (typeof value === "object") {
        for (const [key, item] of Object.entries(value)) visit(item, trail ? `${trail}.${key}` : key);
      }
    };
    visit(parsed.fingerprint ?? parsed.fingerprints ?? null, "fingerprint");
    visit(parsed.acl ?? parsed.acls ?? null, "acl");
    visit(parsed.default_acl_canonical ?? null, "default_acl_canonical");
    visit(parsed.sealedPlatformAclEnvelopeDigest ?? null, "sealedPlatformAclEnvelopeDigest");
    visit(parsed.platformAclCalibration ?? null, "platformAclCalibration");
    if (semanticBlobs.length > 0 || (parsed.default_acl_canonical && redactRe.test(JSON.stringify(parsed.default_acl_canonical)))) {
      return {
        ok: false,
        reason: "HOLD: semantic fingerprint mutation during sanitization",
        code: "F3_SEMANTIC_SANITIZE",
        paths: semanticBlobs,
      };
    }
  }
  if (redactRe.test(output) && /identity_arguments|privilege_type|service_role/.test(output)
    && output.includes("[REDACTED]")
    && /"(?:acl|acls|default_acl_canonical|privilege)"\s*:\s*"[^"]*\[REDACTED\]/.test(output)) {
    return {
      ok: false,
      reason: "HOLD: semantic fingerprint mutation during sanitization",
      code: "F3_SEMANTIC_SANITIZE",
    };
  }
  return { ok: true };
}

export function commitQualifyEvidenceOrHold({ dest, payload, extraSecrets = [] } = {}) {
  const json = typeof payload === "string" ? payload : JSON.stringify(payload, null, 2);
  try {
    const written = writeQualifyEvidenceArtifacts({
      dest,
      sanitizedJson: json,
      extraSecrets,
    });
    return { ok: true, hold: false, ...written };
  } catch (err) {
    return {
      ok: false,
      hold: true,
      status: "HOLD",
      verdict: "HOLD",
      reason: `${EVIDENCE_WRITE_HOLD}: ${err?.message || err}`,
      code: err?.code || "F3_EVIDENCE_WRITE",
      exitCode: 1,
      dbPushCalls: payload?.dbPushCalls,
      repairCalls: 0,
      continuationCalls: 0,
    };
  }
}

export const INVENTORY_PHASES = Object.freeze({
  BEFORE_RESET: "before_reset",
  CLEAN_BASELINE: "CLEAN_BASELINE",
  AFTER_FLOOR: "after_floor",
  AFTER_FAILED_HISTORY: "after_failed_history_insertion",
  AFTER_REPAIR: "after_repair",
  AFTER_RETRY: "after_retry",
  AFTER_CONTINUATION: "after_continuation",
  FINAL: "FINAL",
});

export function labelInventoryCapture({ phase, body, file = null } = {}) {
  if (!phase) {
    return { ok: false, reason: "HOLD: inventory capture missing phase" };
  }
  if (phase === INVENTORY_PHASES.FINAL && (file || phase === INVENTORY_PHASES.BEFORE_RESET)) {
    return { ok: false, reason: "HOLD: purported final inventory captured before final DB state" };
  }
  return {
    ok: true,
    phase,
    file,
    body: body ?? null,
    is_final: phase === INVENTORY_PHASES.FINAL,
  };
}

export function assertFinalInventoryChronology({
  inventories = {},
  historyRows = [],
  recognition = [],
  poisonPresent = null,
  poisonVerified = false,
  historyVerified = false,
  poisonSequence = null,
  historySequence = null,
  finalInventorySequence = null,
  capturedBeforePoison = false,
  capturedBeforeHistory = false,
} = {}) {
  if (inventories[INVENTORY_PHASES.BEFORE_RESET]?.is_final === true
    || inventories[INVENTORY_PHASES.CLEAN_BASELINE]?.is_final === true
    || inventories[INVENTORY_PHASES.AFTER_FLOOR]?.is_final === true) {
    return {
      ok: false,
      reason: "HOLD: purported final inventory captured before final DB state",
      code: "F3_INVENTORY_PREMATURE_FINAL",
    };
  }
  if (capturedBeforePoison === true
    || (finalInventorySequence != null && poisonSequence != null && finalInventorySequence <= poisonSequence)) {
    return {
      ok: false,
      reason: "HOLD: FINAL inventory captured before strict poison verification",
      code: "F3_INVENTORY_BEFORE_POISON",
    };
  }
  if (capturedBeforeHistory === true
    || (finalInventorySequence != null && historySequence != null && finalInventorySequence <= historySequence)) {
    return {
      ok: false,
      reason: "HOLD: FINAL inventory captured before final history query",
      code: "F3_INVENTORY_BEFORE_HISTORY",
    };
  }
  if (poisonVerified !== true || poisonPresent !== false) {
    return {
      ok: false,
      reason: "HOLD: FINAL inventory requires proven poison absence first",
      code: "F3_INVENTORY_POISON_NOT_PROVEN",
    };
  }
  if (historyVerified !== true) {
    return {
      ok: false,
      reason: "HOLD: FINAL inventory requires verified six-row F3 history first",
      code: "F3_INVENTORY_HISTORY_NOT_PROVEN",
    };
  }
  const finalInv = inventories[INVENTORY_PHASES.FINAL];
  if (!finalInv || finalInv.phase !== INVENTORY_PHASES.FINAL || finalInv.is_final !== true) {
    return { ok: false, reason: "HOLD: FINAL inventory missing after 00123 + cleanup" };
  }
  const rows = Array.isArray(historyRows) ? historyRows : [];
  if (rows.length !== F3_FORWARD_FILES.length) {
    return {
      ok: false,
      reason: `HOLD: FINAL inventory history must contain six rows, saw ${rows.length}`,
    };
  }
  if (JSON.stringify(recognition) !== JSON.stringify([...RECOGNITION_ALLOWLIST])) {
    return { ok: false, reason: "HOLD: FINAL recognition must be [\"manual_income\"]" };
  }
  const body = finalInv.body || {};
  if (body.financial_private !== true || body.financial_core !== true || body.financial_ledger_epochs !== true) {
    return { ok: false, reason: "HOLD: FINAL inventory missing expected F3 objects" };
  }
  if (poisonPresent === true) {
    return { ok: false, reason: "HOLD: FINAL inventory still has poison/canary" };
  }
  return { ok: true, historyRows: rows.length, recognition };
}

function sourceLabelForFile(file) {
  const match = String(file).match(/^(0011[89]|0012[0-3])/);
  return match ? match[1] : String(file).replace(/\.sql$/i, "");
}

function cloneJson(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function emptyGrantList() {
  return [];
}

function reconstructFunctiondef(routine) {
  const lines = [
    `CREATE FUNCTION ${routine.schema}.${routine.name}(${routine.identity_arguments})`,
    ` RETURNS ${routine.result_type}`,
    ` LANGUAGE ${routine.language}`,
  ];
  if (routine.volatility && routine.volatility !== "volatile") {
    lines.push(` ${String(routine.volatility).toUpperCase()}`);
  }
  if (routine.strict) lines.push(" STRICT");
  if (routine.leakproof) lines.push(" LEAKPROOF");
  if (routine.security_definer) lines.push(" SECURITY DEFINER");
  if (routine.parallel && routine.parallel !== "unsafe") {
    lines.push(` PARALLEL ${String(routine.parallel).toUpperCase()}`);
  }
  if (Array.isArray(routine.proconfig) && routine.proconfig.includes('search_path=""')) {
    lines.push(" SET search_path TO ''");
  }
  lines.push(`AS $function$${routine.definition || ""}$function$`);
  return lines.join("\n");
}

function stripSqlLineComments(sql) {
  const out = [];
  let i = 0;
  let dollar = null;
  while (i < sql.length) {
    if (dollar) {
      const end = sql.indexOf(dollar, i);
      if (end < 0) {
        out.push(sql.slice(i));
        break;
      }
      out.push(sql.slice(i, end + dollar.length));
      i = end + dollar.length;
      dollar = null;
      continue;
    }
    if (sql[i] === "-" && sql[i + 1] === "-") {
      while (i < sql.length && sql[i] !== "\n") i += 1;
      out.push("\n");
      continue;
    }
    if (sql[i] === "$") {
      const m = sql.slice(i).match(/^\$[A-Za-z0-9_]*\$/);
      if (m) {
        dollar = m[0];
        out.push(m[0]);
        i += m[0].length;
        continue;
      }
    }
    out.push(sql[i]);
    i += 1;
  }
  return out.join("");
}

function splitQualifiedName(name, fallbackSchema = "public") {
  const text = String(name).replace(/"/g, "");
  const idx = text.indexOf(".");
  if (idx > 0) return { schema: text.slice(0, idx), name: text.slice(idx + 1) };
  return { schema: fallbackSchema, name: text };
}

function canonicalSqlType(raw) {
  return String(raw || "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\btimestamptz\b/gi, "timestamp with time zone")
    .replace(/\bint4\b/gi, "integer")
    .replace(/\bint8\b/gi, "bigint")
    .replace(/\bint2\b/gi, "smallint")
    .replace(/\bbool\b/gi, "boolean")
    .replace(/\bvarchar\b/gi, "character varying");
}

function stripDefaultClauses(identityArgs) {
  return canonicalSqlType(String(identityArgs || "").replace(/\s+DEFAULT\s+(?:NULL|'[^']*'|[^\s,]+)/gi, ""));
}

function splitTopLevelSql(text, sep = ",") {
  const parts = [];
  let start = 0;
  let depth = 0;
  let dollar = null;
  for (let i = 0; i < text.length; i += 1) {
    if (dollar) {
      if (text.startsWith(dollar, i)) {
        i += dollar.length - 1;
        dollar = null;
      }
      continue;
    }
    if (text[i] === "$") {
      const m = text.slice(i).match(/^\$[A-Za-z0-9_]*\$/);
      if (m) {
        dollar = m[0];
        i += m[0].length - 1;
        continue;
      }
    }
    if (text[i] === "(") depth += 1;
    else if (text[i] === ")") depth = Math.max(0, depth - 1);
    else if (text[i] === sep && depth === 0) {
      parts.push(text.slice(start, i));
      start = i + 1;
    }
  }
  parts.push(text.slice(start));
  return parts.map((part) => part.trim()).filter(Boolean);
}

function parseEnumLabels(body) {
  const labels = [];
  const re = /'((?:\\'|[^'])*)'/g;
  let match;
  while ((match = re.exec(String(body)))) labels.push(match[1].replace(/\\'/g, "'"));
  return labels;
}

function parseCreateFunction(sql, start) {
  const headerEnd = sql.slice(start).search(/\bAS\s+\$/i);
  if (headerEnd < 0) return null;
  const header = sql.slice(start, start + headerEnd);
  const named = header.match(/^CREATE\s+FUNCTION\s+([A-Za-z0-9_.]+)\s*\(/i);
  if (!named) return null;
  const q = splitQualifiedName(named[1]);
  const argsOpen = header.indexOf("(");
  let depth = 0;
  let argsClose = -1;
  for (let i = argsOpen; i < header.length; i += 1) {
    if (header[i] === "(") depth += 1;
    else if (header[i] === ")") {
      depth -= 1;
      if (depth === 0) {
        argsClose = i;
        break;
      }
    }
  }
  if (argsClose < 0) return null;
  const identityArguments = stripDefaultClauses(header.slice(argsOpen + 1, argsClose));
  const after = header.slice(argsClose + 1);
  const ret = after.match(/RETURNS\s+((?:TABLE\s*\([\s\S]+?\)|[A-Za-z0-9_.]+(?:\s+with\s+time\s+zone)?))/i);
  const lang = after.match(/LANGUAGE\s+([A-Za-z0-9_]+)/i);
  const asMatch = sql.slice(start + headerEnd).match(/^AS\s+(\$[A-Za-z0-9_]*\$)/i);
  if (!asMatch) return null;
  const delim = asMatch[1];
  const rel = sql.slice(start + headerEnd);
  const bodyStart = start + headerEnd + rel.indexOf(delim) + delim.length;
  const bodyEnd = sql.indexOf(delim, bodyStart);
  if (bodyEnd < 0) return null;
  const definition = sql.slice(bodyStart, bodyEnd);
  const searchPath = /\bSET\s+search_path\s*=\s*''/i.test(after);
  const routine = {
    schema: q.schema,
    name: q.name,
    identity_arguments: identityArguments,
    result_type: canonicalSqlType(ret ? ret[1].replace(/\s+/g, " ").trim() : ""),
    language: lang ? lang[1].toLowerCase() : "plpgsql",
    owner: "postgres",
    definition,
    volatility: /\bIMMUTABLE\b/i.test(after) ? "immutable" : /\bSTABLE\b/i.test(after) ? "stable" : "volatile",
    parallel: /\bPARALLEL\s+SAFE\b/i.test(after) ? "safe" : /\bPARALLEL\s+RESTRICTED\b/i.test(after) ? "restricted" : "unsafe",
    strict: /\bSTRICT\b|\bRETURNS\s+NULL\s+ON\s+NULL\s+INPUT\b/i.test(after),
    leakproof: /\bLEAKPROOF\b/i.test(after),
    security_definer: /\bSECURITY\s+DEFINER\b/i.test(after),
    proconfig: searchPath ? ['search_path=""'] : [],
    search_path: searchPath ? "{\"search_path=\\\"\\\"\"}" : "",
    acl: emptyGrantList(),
  };
  routine.functiondef = reconstructFunctiondef(routine);
  return routine;
}

function parseCreateTable(sql, match, lastIndex) {
  const q = splitQualifiedName(match[1]);
  let depth = 1;
  let i = lastIndex;
  const start = i;
  for (; i < sql.length; i += 1) {
    if (sql[i] === "(") depth += 1;
    else if (sql[i] === ")") {
      depth -= 1;
      if (depth === 0) break;
    }
  }
  const body = sql.slice(start, i);
  const items = splitTopLevelSql(body);
  const columns = [];
  const constraints = [];
  let ordinal = 0;
  for (const item of items) {
    if (/^(CONSTRAINT|PRIMARY KEY|UNIQUE|CHECK|EXCLUDE|FOREIGN KEY)\b/i.test(item)) {
      const named = item.match(/^CONSTRAINT\s+([A-Za-z0-9_]+)\s+([\s\S]+)$/i);
      constraints.push({
        schema: q.schema,
        relation: q.name,
        name: named ? named[1] : "",
        contype: /PRIMARY KEY/i.test(item) ? "p"
          : /UNIQUE/i.test(item) ? "u"
            : /EXCLUDE/i.test(item) ? "x"
              : /FOREIGN KEY|REFERENCES/i.test(item) ? "f"
                : "c",
        definition: named ? named[2].trim() : item,
      });
      continue;
    }
    const col = item.match(/^([A-Za-z0-9_]+)\s+([\s\S]+)$/);
    if (!col) continue;
    ordinal += 1;
    const rest = col[2];
    const typeMatch = rest.match(/^((?:[A-Za-z0-9_.]+(?:\s+with\s+time\s+zone)?(?:\s*\([^)]*\))?(?:\s*\[\])*)+)/i);
    const typeRaw = typeMatch ? typeMatch[1] : rest.split(/\s+/)[0];
    const typmodMatch = typeRaw.match(/\(([^)]*)\)$/);
    columns.push({
      schema: q.schema,
      relation: q.name,
      ordinal,
      name: col[1],
      type: canonicalSqlType(typeRaw.replace(/\s*\([^)]*\)$/, "")),
      typmod: typmodMatch ? typmodMatch[1] : null,
      nullable: !/\bNOT NULL\b/i.test(rest) && !/\bPRIMARY KEY\b/i.test(rest),
      default: (() => {
        const found = rest.match(/\bDEFAULT\s+((?:(?!\bCONSTRAINT\b|\bNOT NULL\b|\bNULL\b|\bPRIMARY KEY\b|\bUNIQUE\b|\bCHECK\b|\bREFERENCES\b|\bCOLLATE\b|\bGENERATED\b).)+)/i);
        return found ? found[1].trim() : null;
      })(),
      identity: /\bGENERATED\s+ALWAYS\s+AS\s+IDENTITY\b/i.test(rest)
        ? "always"
        : /\bGENERATED\s+BY DEFAULT\s+AS\s+IDENTITY\b/i.test(rest)
          ? "by_default"
          : null,
      generated: /\bGENERATED\s+ALWAYS\s+AS\b/i.test(rest) && !/\bIDENTITY\b/i.test(rest) ? "stored" : null,
      collation: (() => {
        const found = rest.match(/\bCOLLATE\s+([A-Za-z0-9_."]+)/i);
        return found ? found[1] : null;
      })(),
    });
    if (/\bPRIMARY KEY\b/i.test(rest)) {
      constraints.push({
        schema: q.schema,
        relation: q.name,
        name: `${q.name}_pkey`,
        contype: "p",
        definition: `PRIMARY KEY (${col[1]})`,
      });
    }
  }
  return {
    relation: {
      schema: q.schema,
      name: q.name,
      relkind: "r",
      persistence: "permanent",
      owner: "postgres",
      replica_identity: "default",
      rls_enabled: false,
      rls_force: false,
      acl: emptyGrantList(),
    },
    columns,
    constraints,
  };
}

function readAuthorizedMigrationSql(file) {
  const abs = path.join(repoRoot, "supabase", "migrations", file);
  if (!fs.existsSync(abs)) {
    throw new Error(`HOLD: authorized migration missing for offline fingerprint: ${file}`);
  }
  const bytes = fs.readFileSync(abs);
  const digest = sha256Buffer(bytes);
  if (digest !== FROZEN_DIGESTS[file]) {
    throw new Error(`HOLD: offline fingerprint builder saw digest drift for ${file}`);
  }
  return stripSqlLineComments(bytes.toString("utf8"));
}

function emptyCatalogState() {
  return {
    schemas: [],
    relations: [],
    columns: [],
    types: [],
    views: [],
    routines: [],
    rls: [],
    constraints: [],
    indexes: [],
    triggers: [],
    schemaAcl: {},
  };
}

function applyMigrationSqlToCatalog(state, sql) {
  const schemaRe = /CREATE\s+SCHEMA(?:\s+IF\s+NOT\s+EXISTS)?\s+([A-Za-z0-9_]+)/gi;
  let match;
  while ((match = schemaRe.exec(sql))) {
    if (!state.schemas.some((row) => row.name === match[1])) {
      state.schemas.push({ name: match[1], owner: "postgres", acl: emptyGrantList() });
    }
  }
  const usageGrant = /GRANT\s+USAGE\s+ON\s+SCHEMA\s+([A-Za-z0-9_]+)\s+TO\s+([A-Za-z0-9_,\s]+)/gi;
  while ((match = usageGrant.exec(sql))) {
    const schema = state.schemas.find((row) => row.name === match[1]);
    if (!schema) continue;
    for (const role of match[2].split(",").map((part) => part.trim()).filter(Boolean)) {
      schema.acl.push({
        grantee: role,
        grantor: "postgres",
        privilege: "USAGE",
        grantable: false,
      });
    }
  }
  const typeRe = /CREATE\s+TYPE\s+([A-Za-z0-9_.]+)\s+AS\s+ENUM\s*(\([\s\S]*?\))/gi;
  while ((match = typeRe.exec(sql))) {
    const q = splitQualifiedName(match[1]);
    state.types.push({
      schema: q.schema,
      name: q.name,
      kind: "enum",
      labels: parseEnumLabels(match[2]),
      owner: "postgres",
      acl: emptyGrantList(),
    });
  }
  const tableRe = /CREATE\s+TABLE\s+([A-Za-z0-9_.]+)\s*\(/gi;
  while ((match = tableRe.exec(sql))) {
    const parsed = parseCreateTable(sql, match, tableRe.lastIndex);
    state.relations.push(parsed.relation);
    state.columns.push(...parsed.columns);
    state.constraints.push(...parsed.constraints);
  }
  const fnRe = /CREATE\s+FUNCTION\s+/gi;
  while ((match = fnRe.exec(sql))) {
    const routine = parseCreateFunction(sql, match.index);
    if (routine) state.routines.push(routine);
  }
  const rlsEnable = /ALTER\s+TABLE\s+([A-Za-z0-9_.]+)\s+ENABLE\s+ROW\s+LEVEL\s+SECURITY/gi;
  const rlsForce = /ALTER\s+TABLE\s+([A-Za-z0-9_.]+)\s+FORCE\s+ROW\s+LEVEL\s+SECURITY/gi;
  const enabled = new Set();
  const forced = new Set();
  while ((match = rlsEnable.exec(sql))) enabled.add(match[1].replace(/"/g, ""));
  while ((match = rlsForce.exec(sql))) forced.add(match[1].replace(/"/g, ""));
  for (const rel of state.relations) {
    const key = `${rel.schema}.${rel.name}`;
    const alt = rel.schema === "public" ? rel.name : key;
    if (enabled.has(key) || enabled.has(alt)) rel.rls_enabled = true;
    if (forced.has(key) || forced.has(alt)) rel.rls_force = true;
  }
  const idxRe = /CREATE\s+(UNIQUE\s+)?INDEX\s+([A-Za-z0-9_]+)\s+ON\s+([A-Za-z0-9_.]+)\s*([\s\S]*?);/gi;
  while ((match = idxRe.exec(sql))) {
    const q = splitQualifiedName(match[3]);
    state.indexes.push({
      schema: q.schema,
      relation: q.name,
      name: match[2],
      unique: Boolean(match[1]),
      definition: `CREATE ${match[1] ? "UNIQUE " : ""}INDEX ${match[2]} ON ${match[3]} ${match[4].trim()}`,
    });
  }
  const trgRe = /CREATE\s+(CONSTRAINT\s+)?TRIGGER\s+([A-Za-z0-9_]+)\s+([\s\S]*?)\s+ON\s+([A-Za-z0-9_.]+)\s+([\s\S]*?)EXECUTE\s+FUNCTION\s+([A-Za-z0-9_.]+)\s*\(([\s\S]*?)\);/gi;
  while ((match = trgRe.exec(sql))) {
    const q = splitQualifiedName(match[4]);
    state.triggers.push({
      schema: q.schema,
      relation: q.name,
      name: match[2],
      constraint_trigger: Boolean(match[1]),
      timing_events: match[3].replace(/\s+/g, " ").trim(),
      for_each: /FOR EACH ROW/i.test(match[5]) ? "row" : /FOR EACH STATEMENT/i.test(match[5]) ? "statement" : "",
      function_identity: `${match[6]}(${stripDefaultClauses(match[7])})`,
    });
  }
  return state;
}

function explicitRlsRecords(relations) {
  return relations.map((rel) => ({
    schema: rel.schema,
    relation: rel.name,
    rls_enabled: rel.rls_enabled === true,
    rls_force: rel.rls_force === true,
  }));
}

function attachRoutineAclFromFunctionOwnerAndAcl(routines, functionOwner, aclRows) {
  for (const routine of routines) {
    const ownerRow = (functionOwner || []).find((row) => (
      row.schema === routine.schema
      && row.function === routine.name
      && row.identity_arguments === routine.identity_arguments
    ));
    if (ownerRow) {
      routine.owner = ownerRow.owner;
      routine.security_definer = ownerRow.security_definer;
      if (ownerRow.search_path) routine.search_path = ownerRow.search_path;
    }
    routine.acl = (aclRows || []).filter((row) => (
      row.object_type === "routine"
      && row.schema === routine.schema
      && row.object_name === routine.name
      && row.identity_arguments === routine.identity_arguments
    )).map((row) => ({
      grantee: row.grantee,
      grantor: row.grantor,
      privilege: row.privilege,
      grantable: row.grantable,
    }));
  }
  return routines;
}

function attachRelationAcl(relations, aclRows) {
  for (const rel of relations) {
    rel.acl = (aclRows || []).filter((row) => (
      row.object_type === "table"
      && row.schema === rel.schema
      && row.object_name === rel.name
    )).map((row) => ({
      grantee: row.grantee,
      grantor: row.grantor,
      privilege: row.privilege,
      grantable: row.grantable,
    }));
  }
  return relations;
}

export const JS_SQL_PARSER_SUPERSEDED_REASON =
  "SUPERSEDED: JS SQL-parser / reconstructFunctiondef invented incomplete non-PG-deparser shapes (empty types, empty schema ACLs, human trigger timing_events, incomplete constraint/index sets, different column typmod). Replaced by independent local PostgreSQL 17 CATALOG_FINGERPRINT_SQL collector. NOT hosted. NOT production.";

function sha256FileUtf8(relPath) {
  return createHash("sha256").update(fs.readFileSync(path.join(repoRoot, relPath))).digest("hex");
}

function sha256BytesOf(buf) {
  return createHash("sha256").update(buf).digest("hex");
}

function gitBlobSha1(buf) {
  const header = Buffer.from(`blob ${buf.length}\0`, "utf8");
  return createHash("sha1").update(Buffer.concat([header, buf])).digest("hex");
}

export const GIT_VERIFICATION_UNAVAILABLE =
  "HOLD: GIT_VERIFICATION_UNAVAILABLE";

const DEFAULT_GIT_TIMEOUT_MS = 15_000;
let gitRunnerForTests = null;

export function __installGitRunnerForTests(fn) {
  gitRunnerForTests = typeof fn === "function" ? fn : null;
}

export function __resetGitRunnerForTests() {
  gitRunnerForTests = null;
}

function gitFailClosed(reason, extra = {}) {
  return {
    ok: false,
    reason: `${GIT_VERIFICATION_UNAVAILABLE}: ${reason}`,
    code: "GIT_VERIFICATION_UNAVAILABLE",
    closure_complete: false,
    dbPushCalls: 0,
    repairCalls: 0,
    continuationCalls: 0,
    dbAccess: false,
    ...extra,
  };
}

export function runVerifiedGit(args, options = {}) {
  const argv = Array.isArray(args) ? args : [];
  const timeout = Number.isFinite(options.timeoutMs) ? options.timeoutMs : DEFAULT_GIT_TIMEOUT_MS;
  const encoding = options.encoding || "utf8";
  const expectedSchema = options.expectedSchema || null;
  let result;
  try {
    if (gitRunnerForTests) {
      result = gitRunnerForTests(argv, { cwd: options.cwd || repoRoot, encoding, timeout, ...options });
    } else {
      result = spawnSync("git", argv, {
        cwd: options.cwd || repoRoot,
        encoding,
        timeout,
        maxBuffer: options.maxBuffer || 16 * 1024 * 1024,
      });
    }
  } catch (err) {
    return gitFailClosed(`spawn failed: ${err?.message || err}`, { spawnFailed: true });
  }
  if (result == null || typeof result !== "object") {
    return gitFailClosed("spawn returned no result object", { spawnFailed: true });
  }
  if (result.error) {
    return gitFailClosed(`spawn failed: ${result.error.message || result.error}`, { spawnFailed: true });
  }
  if (result.signal || result.signalCode) {
    return gitFailClosed(`signaled ${result.signal || result.signalCode}`, { signal: result.signal || result.signalCode });
  }
  if (result.killed === true || result.timeout === true || result.timedOut === true) {
    return gitFailClosed("timeout", { timeout: true });
  }
  if (!Object.prototype.hasOwnProperty.call(result, "status") || result.status !== 0) {
    return gitFailClosed(`nonzero status ${result.status}`, { status: result.status });
  }
  const stdout = result.stdout;
  if (expectedSchema === "porcelain") {
    if (typeof stdout !== "string") {
      return gitFailClosed("malformed porcelain stdout", { malformed: true });
    }
  }
  if (expectedSchema === "rev-parse") {
    const text = Buffer.isBuffer(stdout) ? stdout.toString("utf8") : String(stdout || "");
    if (!/^[0-9a-f]{40,64}\s*$/.test(text.trim())) {
      return gitFailClosed("malformed rev-parse stdout", { malformed: true });
    }
  }
  if (expectedSchema === "cat-file-blob") {
    if (stdout == null) {
      return gitFailClosed("missing blob stdout", { missingBlob: true });
    }
  }
  if (expectedSchema === "object-exists") {
    const text = Buffer.isBuffer(stdout) ? stdout.toString("utf8") : String(stdout || "");
    if (!/^(blob|tree|commit|tag)\s*$/.test(text.trim())) {
      return gitFailClosed("object does not exist or unexpected type", { missingBlob: true });
    }
  }
  return {
    ok: true,
    status: 0,
    stdout,
    stderr: result.stderr || "",
    args: argv,
  };
}

export function verifyGitBlobIdentity({ relPath, bytes, worktreeSha256 } = {}) {
  if (!relPath || bytes == null) {
    return gitFailClosed("blob identity inputs missing");
  }
  const exists = runVerifiedGit(["cat-file", "-t", `HEAD:${relPath}`], { expectedSchema: "object-exists" });
  if (!exists.ok) return exists;
  const shown = runVerifiedGit(["show", `HEAD:${relPath}`], { encoding: "buffer", expectedSchema: "cat-file-blob" });
  if (!shown.ok) return shown;
  const headBytes = Buffer.isBuffer(shown.stdout) ? shown.stdout : Buffer.from(String(shown.stdout || ""), "utf8");
  const worktree = Buffer.isBuffer(bytes) ? bytes : Buffer.from(bytes);
  if (gitBlobSha1(headBytes) !== gitBlobSha1(worktree) && sha256BytesOf(headBytes) !== sha256BytesOf(worktree)) {
    return {
      ok: true,
      mismatch: true,
      headSha256: sha256BytesOf(headBytes),
      worktreeSha256: worktreeSha256 || sha256BytesOf(worktree),
    };
  }
  return { ok: true, mismatch: false, headSha256: sha256BytesOf(headBytes) };
}

function packageVersionForSpecifier(specifier, pkgJson) {
  const name = specifier.startsWith("@")
    ? specifier.split("/").slice(0, 2).join("/")
    : specifier.split("/")[0];
  const deps = {
    ...(pkgJson.dependencies || {}),
    ...(pkgJson.devDependencies || {}),
    ...(pkgJson.optionalDependencies || {}),
  };
  return deps[name] || null;
}

function resolveLocalSpecifier(fromRel, specifier) {
  if (!specifier.startsWith(".") && !specifier.startsWith("/")) return null;
  const fromDir = path.dirname(fromRel);
  const joined = path.normalize(path.join(fromDir, specifier)).replaceAll("\\", "/");
  const candidates = [joined];
  if (!path.extname(joined)) {
    candidates.push(`${joined}.mjs`, `${joined}.js`, `${joined}.cjs`, path.join(joined, "index.mjs"));
  }
  for (const candidate of candidates) {
    const rel = candidate.replaceAll("\\", "/");
    if (fs.existsSync(path.join(repoRoot, rel)) && fs.statSync(path.join(repoRoot, rel)).isFile()) {
      return rel;
    }
  }
  return joined;
}

function parseRuntimeSpecifiers(source) {
  const stripped = String(source)
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/(^|[^:])\/\/.*$/gm, "$1");
  const specifiers = [];
  const fromRe = /\b(?:import|export)\s+(?:type\s+)?(?:[\w*{}\s,]*?)\sfrom\s+["']([^"']+)["']/g;
  const sideEffectRe = /\bimport\s+["']([^"']+)["']/g;
  const dynamicRe = /\bimport\s*\(\s*["']([^"']+)["']\s*\)/g;
  let match;
  while ((match = fromRe.exec(stripped))) specifiers.push({ specifier: match[1], kind: "static" });
  while ((match = sideEffectRe.exec(stripped))) specifiers.push({ specifier: match[1], kind: "static" });
  while ((match = dynamicRe.exec(stripped))) specifiers.push({ specifier: match[1], kind: "dynamic" });
  return specifiers;
}

function parseDeterministicSqlFilenames(source) {
  const names = new Set();
  const re = /\b((?:00115_s0_p0b_cut2_notification_queue|00117_m2_notification_policy_foundation|(?:0011[89]|0012[0-3])_f3_[A-Za-z0-9_]+)\.sql)\b/g;
  let match;
  while ((match = re.exec(String(source)))) names.add(match[1]);
  return [...names];
}

export const REQUIRED_RUNTIME_READ_INPUTS = Object.freeze([
  Object.freeze({
    path: "supabase/migrations/00115_s0_p0b_cut2_notification_queue.sql",
    why: "extractEnqueueCreateSql reads the Cut-2 queue migration at floor install",
  }),
  Object.freeze({
    path: "supabase/migrations/00117_m2_notification_policy_foundation.sql",
    why: "stub/live-pin floor copies unmodified 00117 bytes onto the disposable",
  }),
  Object.freeze({
    path: "scripts/_cut3_live_functiondef_hex.json",
    why: "extractHasGroupPermissionCreateSql decodes the Cut-3 live functiondef hex",
  }),
  Object.freeze({
    path: "src/lib/financial-f3-recognition.ts",
    why: "recognitionFromSource / recognitionFromSourcePin read the SOA allowlist",
  }),
]);

function parseFilesystemReadRelPaths(source, fromRel) {
  const stripped = String(source)
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/(^|[^:])\/\/.*$/gm, "$1");
  const found = [];
  const joinRootRe = /path\.join\(\s*(?:root|repoRoot)\s*,\s*["']([^"']+)["']\s*(?:,\s*([A-Za-z0-9_.]+)\s*)?\)/g;
  let match;
  while ((match = joinRootRe.exec(stripped))) {
    const head = match[1].replaceAll("\\", "/");
    const ident = match[2] || null;
    if (ident) {
      const constRe = new RegExp(`(?:const|let|var|export const)\\s+${ident}\\s*=\\s*["']([^"']+)["']`);
      const resolved = constRe.exec(stripped);
      if (resolved) {
        found.push({
          path: `${head.replace(/\/$/, "")}/${resolved[1]}`.replaceAll(/\/+/g, "/"),
          kind: "filesystem",
        });
        continue;
      }
    }
    found.push({ path: head, kind: "filesystem" });
  }
  const readLiteralRe = /(?:fs\.)?readFileSync\(\s*["']([^"']+)["']/g;
  while ((match = readLiteralRe.exec(stripped))) {
    const rel = match[1].replaceAll("\\", "/");
    if (!rel.startsWith("/") && !rel.includes(":")) found.push({ path: rel, kind: "filesystem" });
  }
  const known = [
    "supabase/migrations/00115_s0_p0b_cut2_notification_queue.sql",
    "supabase/migrations/00117_m2_notification_policy_foundation.sql",
    "scripts/_cut3_live_functiondef_hex.json",
    "src/lib/financial-f3-recognition.ts",
  ];
  for (const rel of known) {
    if (stripped.includes(rel) || stripped.includes(path.basename(rel))) {
      found.push({ path: rel, kind: "filesystem" });
    }
  }
  const uniq = [];
  const seen = new Set();
  for (const item of found) {
    const normalized = item.path.replaceAll("\\", "/").replace(/^\.\//, "");
    if (!normalized || seen.has(normalized)) continue;
    seen.add(normalized);
    uniq.push({ path: normalized, kind: item.kind, from: fromRel });
  }
  return uniq;
}

/**
 * Genuine recursive runtime closure from the hosted qualification entrypoint.
 * Static imports + deterministically resolved dynamic import() literals +
 * frozen 00118–00123 filename literals. Not a hand-maintained file list.
 */
export function buildFunctionalRecursiveRuntimeClosure({
  entrypoint = "scripts/qualify-f3-db-push-disposable.mjs",
} = {}) {
  const pkgJson = JSON.parse(fs.readFileSync(path.join(repoRoot, "package.json"), "utf8"));
  const local = new Map();
  const nonLocal = [];
  const missing = [];
  const unresolved = [];
  const seenNonLocal = new Set();

  function addNonLocal(specifier, kind) {
    const key = `${kind}:${specifier}`;
    if (seenNonLocal.has(key)) return;
    seenNonLocal.add(key);
    if (specifier.startsWith("node:")) {
      nonLocal.push({ specifier, kind: "node_builtin", version: null });
      return;
    }
    nonLocal.push({
      specifier,
      kind: "package",
      version: packageVersionForSpecifier(specifier, pkgJson),
    });
  }

  function walk(rel, parent, justification) {
    const normalized = rel.replaceAll("\\", "/");
    if (local.has(normalized)) {
      const existing = local.get(normalized);
      if (parent && !existing.imported_by.includes(parent)) existing.imported_by.push(parent);
      return;
    }
    const abs = path.join(repoRoot, normalized);
    if (!fs.existsSync(abs) || !fs.statSync(abs).isFile()) {
      missing.push({ path: normalized, imported_by: parent || null, justification });
      return;
    }
    const buf = fs.readFileSync(abs);
    local.set(normalized, {
      path: normalized,
      sha256: sha256BytesOf(buf),
      git_blob: gitBlobSha1(buf),
      bytes: buf.byteLength,
      imported_by: parent ? [parent] : ["<entrypoint>"],
      justification,
      why_reachable: justification,
      reading_parent: parent || "<entrypoint>",
      reachability: /filesystem read/.test(justification) ? "filesystem" : /import/.test(justification) ? "static" : "static",
    });
    if (!/\.(mjs|js|cjs)$/.test(normalized)) return;
    const source = buf.toString("utf8");
    for (const item of parseRuntimeSpecifiers(source)) {
      if (item.specifier.startsWith("node:") || (!item.specifier.startsWith(".") && !item.specifier.startsWith("/"))) {
        addNonLocal(item.specifier, item.kind);
        continue;
      }
      const resolved = resolveLocalSpecifier(normalized, item.specifier);
      if (!resolved || !fs.existsSync(path.join(repoRoot, resolved))) {
        unresolved.push({ specifier: item.specifier, from: normalized, kind: item.kind });
        continue;
      }
      walk(resolved, normalized, `${item.kind} import from ${normalized}`);
    }
    for (const fileName of parseDeterministicSqlFilenames(source)) {
      const mig = `supabase/migrations/${fileName}`;
      if (fs.existsSync(path.join(repoRoot, mig))) {
        walk(mig, normalized, `deterministic F3 migration filename literal from ${normalized}`);
      }
    }
    for (const item of parseFilesystemReadRelPaths(source, normalized)) {
      const absRead = path.join(repoRoot, item.path);
      if (fs.existsSync(absRead) && fs.statSync(absRead).isDirectory()) {
        continue;
      }
      if (!fs.existsSync(absRead) || !fs.statSync(absRead).isFile()) {
        missing.push({
          path: item.path,
          imported_by: normalized,
          justification: `runtime filesystem read from ${normalized}`,
          kind: "filesystem",
        });
        continue;
      }
      walk(item.path, normalized, `runtime filesystem read from ${normalized}`);
      const rec = local.get(item.path.replaceAll("\\", "/"));
      if (rec) rec.reachability = rec.reachability || "filesystem";
    }
  }

  walk(entrypoint, null, "hosted qualification entrypoint");

  let uncommitted_functional_diffs = 0;
  let hosted_tree_mismatches = 0;
  let git_verification = { ok: true };
  const rev = runVerifiedGit(["rev-parse", "HEAD"], { expectedSchema: "rev-parse" });
  if (!rev.ok) {
    git_verification = rev;
  }
  for (const rel of local.keys()) {
    if (!git_verification.ok) break;
    const status = runVerifiedGit(["status", "--porcelain", "--", rel], { expectedSchema: "porcelain" });
    if (!status.ok) {
      git_verification = status;
      break;
    }
    if (String(status.stdout || "").trim()) uncommitted_functional_diffs += 1;
    const blob = verifyGitBlobIdentity({
      relPath: rel,
      bytes: fs.readFileSync(path.join(repoRoot, rel)),
      worktreeSha256: local.get(rel).sha256,
    });
    if (!blob.ok) {
      git_verification = blob;
      break;
    }
    if (blob.mismatch) hosted_tree_mismatches += 1;
  }

  const files = [...local.keys()].sort();
  const source_sha256 = {};
  for (const rel of files) source_sha256[rel] = local.get(rel).sha256;
  const closure_sha256 = createHash("sha256")
    .update(files.map((rel) => `${rel}:${source_sha256[rel]}`).join("\n"), "utf8")
    .digest("hex");
  const unexplained_exclusions = 0;
  const runtimeReadRequired = REQUIRED_RUNTIME_READ_INPUTS.map((item) => item.path);
  const runtime_read_missing_paths = runtimeReadRequired.filter((rel) => !files.includes(rel));
  const runtime_read_missing = runtime_read_missing_paths.length
    + missing.filter((item) => item.kind === "filesystem").length;
  const gitOk = git_verification.ok === true;
  const closure_complete = gitOk
    && missing.length === 0
    && unresolved.length === 0
    && runtime_read_missing === 0
    && unexplained_exclusions === 0
    && files.includes(entrypoint)
    && files.includes(INDEPENDENT_REFERENCE_MODULE_RELPATH)
    && F3_FORWARD_FILES.every((file) => files.includes(`supabase/migrations/${file}`))
    && runtimeReadRequired.every((rel) => files.includes(rel));

  return {
    schema: "f3-recursive-runtime-closure-v2",
    entrypoint,
    method: "recursive_static_dynamic_and_runtime_filesystem_reads",
    git_verification: gitOk ? { ok: true } : git_verification,
    git_verification_unavailable: gitOk ? false : true,
    files,
    local: files.map((rel) => local.get(rel)),
    non_local: nonLocal.sort((a, b) => String(a.specifier).localeCompare(String(b.specifier))),
    source_sha256,
    closure_sha256,
    independent_reference_module: INDEPENDENT_REFERENCE_MODULE_RELPATH,
    independent_reference_source_sha256: source_sha256[INDEPENDENT_REFERENCE_MODULE_RELPATH] || null,
    missing: missing.length,
    unresolved: unresolved.length,
    runtime_read_missing,
    runtime_read_missing_paths,
    required_runtime_read_inputs: REQUIRED_RUNTIME_READ_INPUTS,
    unexplained_exclusions,
    uncommitted_functional_diffs,
    hosted_tree_mismatches,
    closure_complete,
    missing_paths: missing,
    unresolved_specifiers: unresolved,
  };
}

export const F3_FUNCTIONAL_RECURSIVE_CLOSURE = Object.freeze((() => {
  const built = buildFunctionalRecursiveRuntimeClosure();
  return {
    ...built,
    files: Object.freeze(built.files),
    local: Object.freeze(built.local),
    non_local: Object.freeze(built.non_local),
    source_sha256: Object.freeze(built.source_sha256),
  };
})());

/** @deprecated Not a recursive closure. Retained only so stale callers fail closed. */
export const F3_FUNCTIONAL_RECURSIVE_CLOSURE_FILES = Object.freeze(
  F3_FUNCTIONAL_RECURSIVE_CLOSURE.files,
);

export const RECURSIVE_CLOSURE_HOLD =
  "HOLD: recursive runtime closure incomplete; db push not spawned; repair not spawned";

export function assertRecursiveClosureReadyForDb(closure = F3_FUNCTIONAL_RECURSIVE_CLOSURE) {
  const missing = Number(closure?.missing ?? -1);
  const unresolved = Number(closure?.unresolved ?? -1);
  const runtime_read_missing = Number(closure?.runtime_read_missing ?? -1);
  const unexplained_exclusions = Number(closure?.unexplained_exclusions ?? -1);
  const uncommitted_functional_diffs = Number(closure?.uncommitted_functional_diffs ?? -1);
  const hosted_tree_mismatches = Number(closure?.hosted_tree_mismatches ?? -1);
  const files = Array.isArray(closure?.files) ? closure.files : [];
  const requiredReads = (closure?.required_runtime_read_inputs || REQUIRED_RUNTIME_READ_INPUTS)
    .map((item) => item.path);
  const runtimeReadAbsent = requiredReads.filter((rel) => !files.includes(rel));
  const gitUnavailable = closure?.git_verification_unavailable === true
    || closure?.git_verification?.ok === false
    || closure?.code === "GIT_VERIFICATION_UNAVAILABLE";
  const ok = !gitUnavailable
    && closure?.closure_complete === true
    && missing === 0
    && unresolved === 0
    && runtime_read_missing === 0
    && unexplained_exclusions === 0
    && uncommitted_functional_diffs === 0
    && hosted_tree_mismatches === 0
    && runtimeReadAbsent.length === 0;
  if (!ok) {
    return {
      ok: false,
      dbAccess: false,
      dbPushCalls: 0,
      repairCalls: 0,
      continuationCalls: 0,
      reason: gitUnavailable ? GIT_VERIFICATION_UNAVAILABLE : RECURSIVE_CLOSURE_HOLD,
      code: gitUnavailable ? "GIT_VERIFICATION_UNAVAILABLE" : undefined,
      failedGate: gitUnavailable ? "git_verification" : "recursive_runtime_closure",
      closure_complete: false,
      missing,
      unresolved,
      runtime_read_missing: runtime_read_missing + runtimeReadAbsent.length,
      unexplained_exclusions,
      uncommitted_functional_diffs,
      hosted_tree_mismatches,
      runtime_read_missing_paths: [
        ...(closure?.runtime_read_missing_paths || []),
        ...runtimeReadAbsent,
      ],
    };
  }
  return {
    ok: true,
    dbAccess: false,
    dbPushCalls: 0,
    repairCalls: 0,
    continuationCalls: 0,
    closure_complete: true,
  };
}

