function requireOracleCatalog(file) {
  const catalog = FROZEN_EXPECTED_ORACLE_CATALOG[file];
  if (!catalog || typeof catalog !== "object" || Array.isArray(catalog)) {
    throw new Error(`HOLD: missing independent local-oracle catalog for ${file}`);
  }
  const actual = createHash("sha256").update(JSON.stringify(FROZEN_EXPECTED_ORACLE_CATALOG), "utf8").digest("hex");
  if (actual !== FROZEN_EXPECTED_ORACLE_CATALOG_SHA256) {
    throw new Error("HOLD: embedded local-oracle catalog digest drifted");
  }
  return catalog;
}

/**
 * Offline expected fingerprint for one cumulative stage.
 * Catalog fields come from the independent local-oracle CATALOG_FINGERPRINT_SQL
 * snapshot (same primitives as the live collector: format_type, pg_get_expr,
 * pg_get_constraintdef, pg_get_indexdef, pg_get_functiondef,
 * pg_get_function_identity_arguments, pg_get_function_result, pg_get_triggerdef,
 * aclexplode). Meta fields come from frozen pins.
 * Never assigned from a hosted/live observed inventory.
 */
export function buildExpandedExpectedFingerprint(file, structuredSeed) {
  if (!F3_FORWARD_FILES.includes(file)) {
    throw new Error(`HOLD: unknown file ${file}`);
  }
  if (
    structuredSeed
    && structuredSeed.migration_digest
    && structuredSeed.migration_digest !== FROZEN_DIGESTS[file]
  ) {
    throw new Error(`HOLD: seed digest drift for ${file}`);
  }
  if (
    structuredSeed
    && Array.isArray(structuredSeed.recognition)
    && JSON.stringify(structuredSeed.recognition) !== JSON.stringify([...RECOGNITION_ALLOWLIST])
  ) {
    throw new Error(`HOLD: seed recognition drift for ${file}`);
  }
  return buildIndependentObservedFingerprint(file, requireOracleCatalog(file));
}

const LOCAL_ORACLE_PREAMBLE_SQL = `
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE SCHEMA IF NOT EXISTS supabase_migrations;
CREATE TABLE IF NOT EXISTS supabase_migrations.schema_migrations (
  version text PRIMARY KEY,
  statements text[],
  name text
);
`;

function applySqlAsPostgresRole(psqlFn, url, sql) {
  return psqlFn(url, `SET ROLE postgres;\n${sql}`);
}

function applyFileAsPostgresRole(psqlFileFn, url, absPath) {
  const sql = fs.readFileSync(absPath);
  const digest = sha256Buffer(sql);
  const tmp = path.join(os.tmpdir(), `f3-oracle-${process.pid}-${path.basename(absPath)}`);
  fs.writeFileSync(tmp, `SET ROLE postgres;\n${sql.toString("utf8")}`);
  try {
    return psqlFileFn(url, tmp);
  } finally {
    try { fs.unlinkSync(tmp); } catch { /* ignore */ }
  }
}

/**
 * Independent local-oracle seal helper. Applies floor + 00117 + 00118–00123
 * on a local PostgreSQL 17 disposable and runs CATALOG_FINGERPRINT_SQL.
 * Never contacts hosted disposable or production.
 */
export async function sealExpectedFingerprintsFromLocalOracle(input = {}) {
  const provenance = { ...EXPECTED_FINGERPRINT_SEAL_PROVENANCE, sealed_in_this_process: true };
  const calibration = evaluatePlatformAclCalibration({
    envelope: Object.prototype.hasOwnProperty.call(input, "platformAclEnvelope")
      ? input.platformAclEnvelope
      : SEALED_PLATFORM_ACL_ENVELOPE,
  });
  if (!calibration.ok) {
    return {
      ok: false,
      status: "HOLD",
      reason: calibration.reason || PLATFORM_ACL_CALIBRATION_HOLD,
      provenance,
      platformAclCalibration: calibration,
    };
  }
  let createDisposableDatabase;
  let psql;
  let psqlFile;
  let psqlAdmin;
  let adminUrl;
  try {
    ({
      createDisposableDatabase,
      psql,
      psqlFile,
      psqlAdmin,
      adminUrl,
    } = input.fixtures || await import("./../fixtures/disposable-postgres.mjs"));
  } catch (err) {
    return {
      ok: false,
      status: "NOT_RUN",
      reason: `local disposable helper unavailable: ${err instanceof Error ? err.message : err}`,
      provenance,
    };
  }
  const installFloor = input.installFloor || installStubLivePinFloorLocal;
  let db;
  const workdir = fs.mkdtempSync(path.join(os.tmpdir(), "f3-oracle-seal-"));
  try {
    db = (input.createDb || createDisposableDatabase)("oracle_seal");
    if (typeof psqlAdmin === "function" && typeof adminUrl === "function") {
      try {
        psqlAdmin(adminUrl(), `ALTER ROLE ubuntu IN DATABASE ${db.name} SET role TO postgres;`);
      } catch {
        /* SET ROLE on each statement is sufficient */
      }
    }
    const appliedDefaults = applyPlatformAclEnvelopeToLocalOracle({
      envelope: calibration.envelope,
      applySql: (sql) => {
        if (/ALTER DEFAULT PRIVILEGES/i.test(sql)) {
          return applySqlAsPostgresRole(psql, db.url, sql);
        }
        return psql(db.url, sql);
      },
    });
    if (!appliedDefaults.ok) {
      return {
        ok: false,
        status: "HOLD",
        reason: appliedDefaults.reason || PLATFORM_ACL_CALIBRATION_HOLD,
        provenance,
        platformAclCalibration: calibration,
      };
    }
    applySqlAsPostgresRole(psql, db.url, LOCAL_ORACLE_PREAMBLE_SQL);
    const installed = installFloor({
      url: db.url,
      workdir,
      psql: (url, query) => applySqlAsPostgresRole(psql, url, query),
      psqlFile: (url, abs) => applyFileAsPostgresRole(psqlFile, url, abs),
    });
    if (!installed?.installed || !installed?.reached_00117) {
      return {
        ok: false,
        status: "HOLD",
        reason: `local-oracle floor did not reach 00117 (${installed?.failedAt || "unknown"})`,
        floor: installed,
        provenance,
      };
    }
    const hashes = {};
    const catalogs = {};
    const primaryStructured = {};
    const independentStructured = {};
    const stageComparisons = {};
    let serverVersion = null;
    try {
      serverVersion = applySqlAsPostgresRole(psql, db.url, "SHOW server_version;");
    } catch {
      serverVersion = null;
    }
    const queryIndependent = (sql) => applySqlAsPostgresRole(psql, db.url, sql);
    for (const file of F3_FORWARD_FILES) {
      const abs = path.join(repoRoot, "supabase", "migrations", file);
      const bytes = fs.readFileSync(abs);
      if (sha256Buffer(bytes) !== FROZEN_DIGESTS[file]) {
        throw new Error(`HOLD: local-oracle saw digest drift for ${file}`);
      }
      applyFileAsPostgresRole(psqlFile, db.url, abs);
      const raw = applySqlAsPostgresRole(psql, db.url, CATALOG_FINGERPRINT_SQL);
      let catalog;
      try {
        catalog = JSON.parse(String(raw || "").trim());
      } catch {
        catalog = null;
      }
      if (catalog == null || typeof catalog !== "object" || Array.isArray(catalog)) {
        throw new Error(`HOLD: local-oracle collector returned a non-object catalog for ${file}`);
      }
      const fingerprint = buildIndependentObservedFingerprint(file, catalog);
      const contracts = assertFingerprintAclContracts(fingerprint);
      if (!contracts.ok) {
        throw new Error(`HOLD: local-oracle ACL contract failed for ${file}: ${contracts.reason}`);
      }
      const coverage = assertFullCatalogV2Coverage(fingerprint);
      if (!coverage.ok) {
        throw new Error(`HOLD: local-oracle v2 coverage failed for ${file}: ${coverage.reason}`);
      }
      const sha = fingerprintCanonicalSha256(fingerprint);
      const independentlyEqualsHosted00118 =
        sha === EXPECTED_FINGERPRINT_SEAL_PROVENANCE.hosted_observed_00118_forbidden;
      if (independentlyEqualsHosted00118 && file !== "00118_f3_bounded_financial_epoch_foundation.sql") {
        throw new Error("HOLD: local-oracle hash equals forbidden hosted observed 72af6699 — refuse copy");
      }
      const independent = collectIndependentFullCatalogReference({
        queryText: queryIndependent,
        file,
        migration: {
          file,
          source_label: sourceLabelForFile(file),
          version: PREASSIGNED_VERSIONS[file],
          name: frozenMigrationName(file),
          digest: FROZEN_DIGESTS[file],
          recognition: [...RECOGNITION_ALLOWLIST],
        },
      });
      const compared = compareIndependentStructuredOutputs(
        independentlyNormalizeCatalog(fingerprint),
        independent.fingerprint,
      );
      stageComparisons[file] = {
        ok: compared.ok === true,
        missingKeys: compared.missingKeys,
        extraKeys: compared.extraKeys,
        unequalKeys: compared.unequalKeys,
        primaryHash: compared.leftHash,
        independentHash: compared.rightHash,
        primarySha256: sha,
        independentSha256: independent.sha256,
      };
      primaryStructured[file] = fingerprint;
      independentStructured[file] = independent.fingerprint;
      if (!compared.ok) {
        return {
          ok: false,
          status: "HOLD",
          reason: `HOLD: independent reference disagrees with primary builder for ${file}; seals unset`,
          provenance: {
            ...provenance,
            independent_agrees: false,
            must_reverify_on_17_6: true,
            server_version: serverVersion,
          },
          hashes: null,
          catalogs: null,
          recognition: [...RECOGNITION_ALLOWLIST],
          schema_version: F3_FULL_FINGERPRINT_SCHEMA_VERSION,
          platformAclCalibration: calibration,
          platformAclApplied: appliedDefaults,
          independentAgrees: false,
          stageComparisons,
          primaryStructured,
          independentStructured,
          serverVersion,
          mustReverifyOn176: true,
        };
      }
      hashes[file] = sha;
      catalogs[file] = catalog;
    }
    return {
      ok: true,
      status: "SEALED",
      provenance: {
        ...provenance,
        independent_agrees: true,
        must_reverify_on_17_6: !/^17\.6\b/.test(String(serverVersion || "")),
        server_version: serverVersion,
        independent_reference_source_sha256:
          F3_FUNCTIONAL_RECURSIVE_CLOSURE.independent_reference_source_sha256,
        recursive_closure_sha256: F3_FUNCTIONAL_RECURSIVE_CLOSURE.closure_sha256,
      },
      hashes,
      catalogs,
      recognition: [...RECOGNITION_ALLOWLIST],
      schema_version: F3_FULL_FINGERPRINT_SCHEMA_VERSION,
      platformAclCalibration: calibration,
      platformAclApplied: appliedDefaults,
      independentAgrees: true,
      stageComparisons,
      primaryStructured,
      independentStructured,
      serverVersion,
      mustReverifyOn176: !/^17\.6\b/.test(String(serverVersion || "")),
    };
  } catch (err) {
    const msg = String(err && err.message || err);
    if (
      /connect|could not connect|No such file|server_version|PostgreSQL 17|ECONNREFUSED|f3_|psql admin failed|psql failed|Connection refused|does not exist/i.test(
        msg,
      )
    ) {
      return {
        ok: false,
        status: "NOT_RUN",
        reason: `local PostgreSQL 17 disposable unavailable: ${msg}`,
        provenance,
      };
    }
    return { ok: false, status: "HOLD", reason: msg, provenance };
  } finally {
    try { db?.close?.(); } catch { /* ignore */ }
    fs.rmSync(workdir, { recursive: true, force: true });
  }
}


function fingerprintContainsOid(value) {
  if (value == null || typeof value !== "object") return false;
  if (Array.isArray(value)) return value.some((item) => fingerprintContainsOid(item));
  for (const key of Object.keys(value)) {
    if (/^(oid|pronamespace|regprocedure|regproc|regclass|regtype|regnamespace|tableoid)$/i.test(key)) {
      return true;
    }
    if (fingerprintContainsOid(value[key])) return true;
  }
  return false;
}

function nestedKeyContractErrors(fingerprint) {
  const errors = [];
  for (const [key, required] of Object.entries(F3_FULL_FINGERPRINT_NESTED_KEYS)) {
    if (key === "column_acl") continue;
    if (!Object.prototype.hasOwnProperty.call(fingerprint, key)) continue;
    const value = fingerprint[key];
    if (key === "hgp" || key === "enqueue") {
      if (value == null || typeof value !== "object" || Array.isArray(value)) {
        errors.push(`${key} must be a structured object`);
        continue;
      }
      const keys = Object.keys(value).sort();
      const expected = [...required].sort();
      if (keys.length !== expected.length || keys.some((item, i) => item !== expected[i])) {
        errors.push(`${key} nested keys are not the exact contract`);
      }
      continue;
    }
    if (!Array.isArray(value)) {
      errors.push(`${key} must be an array`);
      continue;
    }
    const seen = new Set();
    for (const record of value) {
      if (record == null || typeof record !== "object" || Array.isArray(record)) {
        errors.push(`${key} record is not an object`);
        continue;
      }
      for (const field of required) {
        if (!Object.prototype.hasOwnProperty.call(record, field)) {
          errors.push(`${key} missing nested key ${field}`);
        }
      }
      for (const extra of Object.keys(record)) {
        if (!required.includes(extra)) {
          errors.push(`${key} unexpected nested key ${extra}`);
        }
      }
      const fingerprintKey = JSON.stringify(canonicalize(record));
      if (seen.has(fingerprintKey)) errors.push(`${key} duplicate records`);
      seen.add(fingerprintKey);
      if (key === "columns") {
        if (!Object.prototype.hasOwnProperty.call(record, "attacl_is_null")
          || !Object.prototype.hasOwnProperty.call(record, "attacl")) {
          errors.push("missing attacl coverage");
        } else if (typeof record.attacl_is_null !== "boolean") {
          errors.push("attacl_is_null must be boolean");
        } else if (!Array.isArray(record.attacl)) {
          errors.push("attacl must be an array of structured tuples");
        } else {
          if (record.attacl_is_null && record.attacl.length > 0) {
            errors.push("NULL attacl cannot carry grant tuples");
          }
          for (const tuple of record.attacl) {
            if (!tuple || typeof tuple !== "object" || Array.isArray(tuple)) {
              errors.push("attacl tuple is not an object");
              continue;
            }
            const keys = Object.keys(tuple).sort();
            const expected = [...F3_FULL_FINGERPRINT_NESTED_KEYS.column_acl].sort();
            if (keys.length !== expected.length || keys.some((item, i) => item !== expected[i])) {
              errors.push("attacl tuple keyset mismatch");
            }
          }
        }
      }
      if (key === "triggers") {
        if (!Object.prototype.hasOwnProperty.call(record, "tgenabled")) {
          errors.push("missing tgenabled");
        } else if (!["O", "D", "R", "A"].includes(record.tgenabled)) {
          errors.push("tgenabled must be O/D/R/A");
        }
        if (!Object.prototype.hasOwnProperty.call(record, "function_schema")
          || !Object.prototype.hasOwnProperty.call(record, "function_name")
          || !Object.prototype.hasOwnProperty.call(record, "function_identity_arguments")) {
          errors.push("missing trigger function identity");
        }
        if (!["BEFORE", "AFTER", "INSTEAD"].includes(record.timing)) {
          errors.push("trigger timing must be decoded from tgtype");
        }
        if (!["ROW", "STATEMENT"].includes(record.level)) {
          errors.push("trigger level must be decoded from tgtype");
        }
        if (typeof record.events !== "string" || record.events.length === 0) {
          errors.push("trigger events must be decoded from tgtype");
        }
        if (typeof record.multiplicity !== "number" || !Number.isInteger(record.multiplicity) || record.multiplicity < 1) {
          errors.push("trigger multiplicity must be a positive integer");
        }
        if (typeof record.tgdeferrable !== "boolean" || typeof record.tginitdeferred !== "boolean") {
          errors.push("per-trigger tgdeferrable/tginitdeferred must be boolean");
        }
        if (typeof record.condeferrable !== "boolean" || typeof record.condeferred !== "boolean") {
          errors.push("constraint-level condeferrable/condeferred must be boolean");
        }
        if (Object.prototype.hasOwnProperty.call(record, "deferrable")
          || Object.prototype.hasOwnProperty.call(record, "initially_deferred")) {
          errors.push("constraint-level defer must not substitute for per-trigger flags");
        }
        if (!["user", "referencing_action", "referenced_action", "constraint_other"].includes(record.action_role)) {
          errors.push("trigger action_role is not a v5 RI-enforcement role");
        }
        if (record.action_role == null || record.action_role === "") {
          errors.push("trigger action_role missing; unknown/ambiguous RI mapping holds closed");
        }
        if (typeof record.referencing_schema !== "string" || typeof record.referencing_relation !== "string") {
          errors.push("trigger referencing association missing");
        }
        if (typeof record.constraint_association !== "boolean") {
          errors.push("missing constraint association");
        }
        if (!Array.isArray(record.update_columns)) {
          errors.push("update_columns must be an array");
        }
        if (Object.prototype.hasOwnProperty.call(record, "oid") || Object.prototype.hasOwnProperty.call(record, "name")) {
          errors.push("trigger record must not include OID or generated name");
        }
        if (record.tgisinternal === true) {
          if (record.user_trigger_name !== "" || record.user_definition !== "") {
            errors.push("internal constraint trigger must omit generated name/definition");
          }
          if (record.constraint_association !== true || !record.constraint_name) {
            errors.push("internal constraint trigger missing constraint association");
          }
        }
        const blob = JSON.stringify(record);
        if (/RI_ConstraintTrigger/i.test(blob)) {
          errors.push("generated internal trigger name is not a stable identity");
        }
      }
    }
  }
  if (Object.prototype.hasOwnProperty.call(fingerprint, "columns") && !Array.isArray(fingerprint.columns)) {
    errors.push("missing attacl coverage");
  }
  if (Object.prototype.hasOwnProperty.call(fingerprint, "triggers") && !Array.isArray(fingerprint.triggers)) {
    errors.push("missing tgenabled");
  }
  return errors;
}

const VERSIONED_SECURITY_FIELDS = Object.freeze(new Set([
  ...FINGERPRINT_ALLOWED_KEYS,
  "column_acl",
]));

export function assertFullCatalogV2Coverage(fingerprint) {
  if (!fingerprint || typeof fingerprint !== "object" || Array.isArray(fingerprint)) {
    return { ok: false, reason: "fingerprint missing or not an object" };
  }
  if (fingerprint.schema_version !== F3_FULL_FINGERPRINT_SCHEMA_VERSION) {
    return { ok: false, reason: "fingerprint schema_version mismatch" };
  }
  for (const key of Object.keys(fingerprint)) {
    if (!VERSIONED_SECURITY_FIELDS.has(key)) {
      return { ok: false, reason: `extra unknown security field ${key}` };
    }
  }
  if (!Array.isArray(fingerprint.triggers)) {
    return { ok: false, reason: "missing tgenabled" };
  }
  if (!Array.isArray(fingerprint.columns)) {
    return { ok: false, reason: "missing attacl coverage" };
  }
  const nested = nestedKeyContractErrors(fingerprint);
  if (nested.length > 0) {
    return { ok: false, reason: nested[0] };
  }
  return { ok: true };
}

