const SQL_FAILURE_LINE = /(?:^|[\s:])(?:ERROR|FATAL|PANIC):/i;
const ENVELOPE_ALLOWED_KEYS = Object.freeze(["rows", "advisory", "warning"]);

export function textOf(input) {
  return `${input?.stdout || ""}\n${input?.stderr || ""}\n${input?.output || ""}`;
}

export function hasSqlFailureOutput(text) {
  return String(text || "")
    .split(/\r?\n/)
    .some((line) => SQL_FAILURE_LINE.test(line));
}

export function extractSqlFailureLines(text) {
  const fromPsql = extractPsqlErrorLines(text);
  const extra = String(text || "")
    .split(/\r?\n/)
    .map((line) => line.trimEnd())
    .filter((line) => {
      if (!line) return false;
      if (/^\s*(NOTICE|WARNING):/i.test(line)) return false;
      return /(?:^|[\s:])(?:FATAL|PANIC):/i.test(line);
    });
  return [...fromPsql, ...extra];
}

export function hasTargetSpecificInjectMarker(text, version) {
  const blob = String(text || "");
  if (!blob.includes(HISTORY_INJECT_MARKER)) return false;
  if (!String(version || "")) return false;
  const v = String(version);
  return (
    blob.includes(`version ${v}`) ||
    blob.includes(`for version ${v}`) ||
    new RegExp(`${HISTORY_INJECT_MARKER}[^\\n]*${v}`).test(blob)
  );
}

export function unrelatedMigrationSqlErrors(text, version, extraText = "") {
  const combined = extraText ? `${text || ""}\n${extraText}` : text;
  const lines = extractSqlFailureLines(combined);
  return lines.filter((line) => {
    if (hasTargetSpecificInjectMarker(line, version)) return false;
    if (line.includes(HISTORY_INJECT_MARKER) && String(line).includes(String(version))) {
      return false;
    }
    return true;
  });
}

export function canonicalize(value) {
  if (value === null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map((item) => canonicalize(item));
  const out = {};
  for (const key of Object.keys(value).sort()) {
    out[key] = canonicalize(value[key]);
  }
  return out;
}

export function canonicalDeepEqual(a, b) {
  return JSON.stringify(canonicalize(a)) === JSON.stringify(canonicalize(b));
}

function sameKeySet(a, b) {
  const ka = Object.keys(a).sort();
  const kb = Object.keys(b).sort();
  if (ka.length !== kb.length) return false;
  return ka.every((key, i) => key === kb[i]);
}

function parseEntireJson(stdout) {
  if (stdout == null) return { ok: false, reason: "stdout missing" };
  const raw = String(stdout).trim();
  if (!raw) return { ok: false, reason: "empty" };
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch {
    return { ok: false, reason: "non-JSON" };
  }
}

export function expectedIdentitiesForExpression(expression) {
  const classified = classifyObjectProbeExpression(expression);
  if (!classified) return Object.freeze([]);
  return Object.freeze([classified.lookup]);
}

export function expectedRowForFile(file) {
  const descriptors = getFrozenExpectedObjectProbeDescriptors(file);
  const row = {};
  descriptors.forEach((descriptor, i) => {
    row[`p${i}`] = descriptor;
  });
  return row;
}

function rowFromSupportedProbeSchema(parsed) {
  if (Array.isArray(parsed)) {
    if (parsed.length !== 1) return { ok: false, reason: "wrong JSON shape: expected exactly one row" };
    const row = parsed[0];
    if (!row || typeof row !== "object" || Array.isArray(row)) {
      return { ok: false, reason: "wrong JSON shape: row is not an object" };
    }
    return { ok: true, schema: "array_rows", row };
  }
  if (parsed && typeof parsed === "object") {
    const unexpected = Object.keys(parsed).filter((k) => !ENVELOPE_ALLOWED_KEYS.includes(k));
    if (unexpected.length > 0 && !Array.isArray(parsed.rows)) {
      return { ok: false, reason: "wrong JSON shape" };
    }
    if (!Array.isArray(parsed.rows)) {
      return { ok: false, reason: "wrong JSON shape: missing rows" };
    }
    if (parsed.rows.length !== 1) {
      return { ok: false, reason: "wrong JSON shape: expected exactly one row" };
    }
    const row = parsed.rows[0];
    if (!row || typeof row !== "object" || Array.isArray(row)) {
      return { ok: false, reason: "wrong JSON shape: row is not an object" };
    }
    return { ok: true, schema: "envelope_rows", row };
  }
  return { ok: false, reason: "wrong JSON shape" };
}

/**
 * Strict object-probe parse at the catalog boundary.
 * Presence is accepted ONLY when every listed condition holds:
 * resolved OID → structured catalog identity exactly equals the
 * independently frozen expected descriptor. Lookup spelling is never
 * compared to to_regprocedure(...)::text. Name-only, partial, reordered,
 * aliased, OID-bearing, duplicated, or unexpected identities fail closed.
 */
export function evaluateObjectProbe(result = {}, { file, expressions } = {}) {
  if (result == null || typeof result !== "object") {
    return { present: false, reason: "probe result missing" };
  }
  if (result.status !== 0) {
    return { present: false, reason: `probe status ${result.status}` };
  }
  const blob = textOf(result);
  if (hasSqlFailureOutput(blob)) {
    return { present: false, reason: "probe SQL error", errors: extractSqlFailureLines(blob) };
  }
  const parsedStdout = parseEntireJson(result.stdout);
  if (!parsedStdout.ok) {
    return { present: false, reason: parsedStdout.reason };
  }
  const shaped = rowFromSupportedProbeSchema(parsedStdout.value);
  if (!shaped.ok) return { present: false, reason: shaped.reason };

  const targetFile = file || result.file;
  const exprs = expressions || result.expressions || TARGET_OBJECT_PROBES[targetFile] || null;
  if (!Array.isArray(exprs) || exprs.length === 0) {
    return { present: false, reason: "expected probe expressions missing" };
  }
  for (const expr of exprs) {
    if (!classifyObjectProbeExpression(expr)) {
      return { present: false, reason: "malformed object-probe expression" };
    }
  }
  let expectedDescriptors;
  try {
    expectedDescriptors = getFrozenExpectedObjectProbeDescriptors(targetFile);
  } catch (err) {
    return { present: false, reason: err instanceof Error ? err.message : "expected probe descriptor missing" };
  }
  if (expectedDescriptors.length !== exprs.length) {
    return { present: false, reason: "frozen expected descriptors do not pair 1:1 with probe expressions" };
  }

  const expectedKeys = exprs.map((_, i) => `p${i}`);
  const observedKeys = Object.keys(shaped.row).sort();
  const expectedKeySet = [...expectedKeys].sort();
  if (!sameKeySet(Object.fromEntries(expectedKeySet.map((k) => [k, true])), Object.fromEntries(observedKeys.map((k) => [k, true])))) {
    return { present: false, reason: "probe row keys are not the complete expected pN set" };
  }

  const missing = [];
  const seenFingerprints = new Set();
  for (let i = 0; i < exprs.length; i += 1) {
    const key = `p${i}`;
    const observed = shaped.row[key];
    const expected = expectedDescriptors[i];
    if (observed == null || observed === false || observed === "f" || observed === "") {
      missing.push(key);
      continue;
    }
    const compared = structuredObjectProbeIdentityExact(observed, expected);
    if (!compared.ok) {
      return { present: false, reason: `p${i} ${compared.reason}` };
    }
    const fingerprint = objectProbeIdentityFingerprint(observed);
    if (seenFingerprints.has(fingerprint)) {
      return { present: false, reason: "duplicate structured probe records" };
    }
    seenFingerprints.add(fingerprint);
  }
  if (missing.length > 0) {
    return { present: false, reason: `required object missing: ${missing.join(",")}` };
  }
  assertExpectedObjectProbeDescriptorsImmutable(targetFile);
  return { present: true, schema: shaped.schema, row: shaped.row };
}

export function objectsPresentFromProbe(result, options) {
  return evaluateObjectProbe(result, options).present === true;
}

export function fingerprintCompleteAndExact(fingerprint, file) {
  if (!fingerprint || typeof fingerprint !== "object" || Array.isArray(fingerprint)) {
    return { ok: false, reason: "fingerprint missing or not an object" };
  }
  const expected = fingerprint.expected;
  const observed = fingerprint.observed;
  if (expected == null || typeof expected !== "object" || Array.isArray(expected)) {
    return { ok: false, reason: "fingerprint.expected missing or not an object" };
  }
  if (observed == null || typeof observed !== "object" || Array.isArray(observed)) {
    return { ok: false, reason: "fingerprint.observed missing or not an object" };
  }
  if (fingerprintContainsOid(expected) || fingerprintContainsOid(observed)) {
    return { ok: false, reason: "fingerprint must not contain OID fields" };
  }
  if (
    expected.schema_version !== F3_FULL_FINGERPRINT_SCHEMA_VERSION
    || observed.schema_version !== F3_FULL_FINGERPRINT_SCHEMA_VERSION
    || expected.schema_version !== observed.schema_version
  ) {
    return { ok: false, reason: "fingerprint schema_version mismatch" };
  }
  let expectedHashBefore;
  try {
    expectedHashBefore = fingerprintCanonicalSha256(expected);
  } catch (err) {
    return { ok: false, reason: err instanceof Error ? err.message : "expected fingerprint cannot be hashed" };
  }
  const allowed = new Set(FINGERPRINT_ALLOWED_KEYS);
  for (const key of new Set([...Object.keys(expected), ...Object.keys(observed)])) {
    if (!allowed.has(key)) {
      return { ok: false, reason: `unexpected fingerprint key ${key}` };
    }
  }
  for (const key of FINGERPRINT_REQUIRED_KEYS) {
    if (!Object.prototype.hasOwnProperty.call(expected, key)) {
      return { ok: false, reason: `expected missing key ${key}` };
    }
    if (!Object.prototype.hasOwnProperty.call(observed, key)) {
      return { ok: false, reason: `observed missing key ${key}` };
    }
    if (expected[key] === undefined) {
      return { ok: false, reason: `expected missing key ${key}` };
    }
    if (observed[key] === undefined) {
      return { ok: false, reason: `observed missing key ${key}` };
    }
  }
  const expectedCanon = canonicalizeFingerprintForCompare(expected);
  const observedCanon = canonicalizeFingerprintForCompare(observed);
  if (isFingerprintCanonicalizationRejected(expectedCanon)) {
    return { ok: false, reason: `expected canonicalization rejected: ${expectedCanon.reason}` };
  }
  if (isFingerprintCanonicalizationRejected(observedCanon)) {
    return { ok: false, reason: `observed canonicalization rejected: ${observedCanon.reason}` };
  }
  const expectedCoverage = assertFullCatalogV2Coverage(expectedCanon);
  if (!expectedCoverage.ok) {
    return { ok: false, reason: `expected ${expectedCoverage.reason}` };
  }
  const observedCoverage = assertFullCatalogV2Coverage(observedCanon);
  if (!observedCoverage.ok) {
    return { ok: false, reason: `observed ${observedCoverage.reason}` };
  }
  const nestedErrors = [
    ...nestedKeyContractErrors(expectedCanon),
    ...nestedKeyContractErrors(observedCanon),
  ];
  if (nestedErrors.length > 0) {
    return { ok: false, reason: nestedErrors[0] };
  }
  const presentCatalog = new Set();
  for (const key of [...FINGERPRINT_REQUIRED_KEYS, ...FINGERPRINT_OPTIONAL_CATALOG_KEYS]) {
    if (Object.prototype.hasOwnProperty.call(expected, key) || Object.prototype.hasOwnProperty.call(observed, key)) {
      presentCatalog.add(key);
    }
  }
  for (const key of presentCatalog) {
    if (!Object.prototype.hasOwnProperty.call(expected, key)) {
      return { ok: false, reason: `expected missing key ${key}` };
    }
    if (!Object.prototype.hasOwnProperty.call(observed, key)) {
      return { ok: false, reason: `observed missing key ${key}` };
    }
  }
  if (!sameKeySet(expected, observed)) {
    return { ok: false, reason: "expected/observed key sets differ (missing or unexpected keys)" };
  }
  if (expected.f3_objects_absent === true || observed.f3_objects_absent === true) {
    return { ok: false, reason: "fingerprint f3_objects_absent is true after target apply" };
  }
  const expectedAcl = assertFingerprintAclContracts(expected);
  if (!expectedAcl.ok) {
    return { ok: false, reason: `expected ${expectedAcl.reason}` };
  }
  const observedAcl = assertFingerprintAclContracts(observed);
  if (!observedAcl.ok) {
    return { ok: false, reason: `observed ${observedAcl.reason}` };
  }
  if (!canonicalFingerprintEqual(expected, observed)) {
    return { ok: false, reason: "fingerprint expected and observed are not canonically equal" };
  }
  let expectedHashAfter;
  try {
    expectedHashAfter = fingerprintCanonicalSha256(expected);
  } catch (err) {
    return { ok: false, reason: err instanceof Error ? err.message : "expected fingerprint cannot be hashed after compare" };
  }
  if (expectedHashBefore !== expectedHashAfter) {
    return { ok: false, reason: "expected fingerprint mutated during compare" };
  }
  if (file && FROZEN_EXPECTED_FINGERPRINT_SHA256[file]) {
    if (expectedHashAfter !== FROZEN_EXPECTED_FINGERPRINT_SHA256[file]) {
      return { ok: false, reason: "expected fingerprint is not the sealed frozen constant" };
    }
    assertExpectedFingerprintImmutable(file);
  }
  if (Object.prototype.hasOwnProperty.call(fingerprint, "independent")) {
    const independentAgree = evaluateIndependentReferenceAgreement({
      primary: observed,
      independent: fingerprint.independent,
    });
    if (!independentAgree.ok) {
      return {
        ok: false,
        reason: independentAgree.reason || "independent_reference_disagreement",
        failedGate: "fingerprint_exact",
      };
    }
  }
  return { ok: true };
}

export function evaluateIndependentReferenceAgreement({ primary, independent } = {}) {
  if (primary == null || independent == null) {
    return { ok: false, reason: "independent_reference_disagreement", missing: true };
  }
  const compared = compareIndependentStructuredOutputs(primary, independent);
  if (!compared.ok) {
    return {
      ok: false,
      reason: "independent_reference_disagreement",
      missingKeys: compared.missingKeys,
      extraKeys: compared.extraKeys,
      unequalKeys: compared.unequalKeys,
    };
  }
  return { ok: true, ...compared };
}

function hashFrozenTargetFields(fields) {
  const payload = {};
  for (const key of FROZEN_TARGET_HASH_FIELDS) {
    payload[key] = fields[key];
  }
  return createHash("sha256").update(JSON.stringify(payload), "utf8").digest("hex");
}

function parseConnectionUrlMetadata(url) {
  if (typeof url !== "string" || !url.startsWith("postgresql://")) {
    return { ok: false, reason: "connection URL is not a postgresql URL" };
  }
  let parsed;
  try {
    parsed = new URL(url);
  } catch {
    return { ok: false, reason: "connection URL is not parseable" };
  }
  const sslmode = parsed.searchParams.get("sslmode");
  return {
    ok: true,
    hostname: parsed.hostname,
    port: Number(parsed.port || 0),
    database: decodeURIComponent((parsed.pathname || "/").replace(/^\//, "")),
    username: decodeURIComponent(parsed.username || ""),
    sslmode,
    ssl_required: sslmode === "require",
  };
}

function mapPoolerUsername(username) {
  const raw = String(username || "");
  const dot = raw.indexOf(".");
  if (dot <= 0 || dot !== raw.lastIndexOf(".")) {
    return { ok: false, reason: "connection username is not role.project_ref" };
  }
  return {
    ok: true,
    expected_live_role: raw.slice(0, dot),
    project_ref: raw.slice(dot + 1),
    connection_username: raw,
  };
}

export function validateConnectionAgainstDisposableAllowlist(connection = {}) {
  const fail = (reason, parser_verdict = "connection_rejected") => ({
    ok: false,
    reason,
    parser_verdict,
    hold: IMMUTABLE_TARGET_HOLD,
    dbAccess: false,
    dbPushCalls: 0,
    repairCalls: 0,
    continuationCalls: 0,
  });
  const hostname = String(connection.hostname || "");
  const port = Number(connection.port);
  const database = String(connection.database || "");
  const username = String(connection.username || "");
  const sslmode = String(connection.sslmode || "");
  const classification = String(connection.host_classification || "");
  const projectRef = String(connection.project_ref || "");
  const orgId = String(connection.org_id || "");
  const projectName = String(connection.project_name || "");

  if (projectRef === PRODUCTION_REF || hostname.includes(PRODUCTION_REF) || username.includes(PRODUCTION_REF)) {
    return fail("production ref", "production_ref");
  }
  if (projectRef && projectRef !== APPROVED_DISPOSABLE_PROJECT_REF) {
    return fail("wrong ref", "wrong_ref");
  }
  if (orgId && orgId !== APPROVED_DISPOSABLE_ORG_ID) {
    return fail("wrong org", "wrong_org");
  }
  if (projectName && projectName !== APPROVED_DISPOSABLE_PROJECT_NAME) {
    return fail("wrong project name", "wrong_name");
  }
  if (port === TRANSACTION_POOLER_PORT) {
    return fail("unapproved pooler port (transaction pooler)", "wrong_port");
  }
  if (port !== APPROVED_DISPOSABLE_POOLER_PORT && port !== APPROVED_DISPOSABLE_PORT) {
    return fail("wrong port", "wrong_port");
  }
  if (database !== APPROVED_DISPOSABLE_DATABASE) {
    return fail("wrong database", "wrong_database");
  }
  if (sslmode !== "require" || connection.ssl_required !== true) {
    return fail("missing SSL", "missing_ssl");
  }
  if (classification === "approved_session_pooler") {
    if (hostname !== APPROVED_DISPOSABLE_POOLER_HOST) {
      return fail("unapproved pooler", "wrong_pooler");
    }
    if (username !== APPROVED_DISPOSABLE_POOLER_USER) {
      return fail("wrong username", "wrong_username");
    }
    if (port !== APPROVED_DISPOSABLE_POOLER_PORT) {
      return fail("wrong port", "wrong_port");
    }
  } else if (classification === "approved_direct_host") {
    if (hostname !== APPROVED_DISPOSABLE_HOST) {
      return fail("wrong/aliased hostname", "wrong_hostname");
    }
    if (username !== APPROVED_DISPOSABLE_USER) {
      return fail("wrong username", "wrong_username");
    }
  } else {
    return fail("unapproved pooler or host classification", "wrong_pooler");
  }
  if (hostname !== APPROVED_DISPOSABLE_POOLER_HOST && hostname !== APPROVED_DISPOSABLE_HOST) {
    return fail("wrong/aliased hostname", "wrong_hostname");
  }
  const mapped = mapPoolerUsername(
    classification === "approved_session_pooler" ? username : `${APPROVED_DISPOSABLE_USER}.${APPROVED_DISPOSABLE_PROJECT_REF}`,
  );
  if (!mapped.ok) return fail(mapped.reason, "username_mapping");
  if (mapped.project_ref !== APPROVED_DISPOSABLE_PROJECT_REF) {
    return fail("username mapping ref mismatch", "username_mapping");
  }
  if (mapped.expected_live_role !== APPROVED_DISPOSABLE_USER) {
    return fail("username mapping role mismatch", "username_mapping");
  }
  return {
    ok: true,
    mapping: Object.freeze({
      connection_username: classification === "approved_session_pooler" ? username : APPROVED_DISPOSABLE_POOLER_USER,
      project_ref: mapped.project_ref,
      expected_live_current_user: mapped.expected_live_role,
      expected_live_current_database: APPROVED_DISPOSABLE_DATABASE,
    }),
  };
}

/**
 * ONE immutable validated target from the exact connection used by floor,
 * db push, poison install/remove, poison probes, fingerprint queries,
 * repair, retry, and continuation. Must be constructed BEFORE database
 * activity. Field provenance is preserved: hostname/pooler/ref/org never
 * claimed to come from SQL.
 */
export function constructImmutableValidatedTargetFromConnection(input = {}) {
  const fail = (reason, parser_verdict = "target_rejected") => ({
    ok: false,
    reason,
    parser_verdict,
    hold: IMMUTABLE_TARGET_HOLD,
    dbAccess: false,
    dbPushCalls: 0,
    repairCalls: 0,
    continuationCalls: 0,
    target: null,
  });

  let hostname = input.connection?.hostname;
  let port = input.connection?.port;
  let database = input.connection?.database;
  let username = input.connection?.username;
  let sslmode = input.connection?.sslmode;
  let sslRequired = input.connection?.ssl_required;
  let classification = input.connection?.host_classification;
  let credentialSource = input.connection?.credential_source;

  if (input.connectionUrl) {
    const parsed = parseConnectionUrlMetadata(input.connectionUrl);
    if (!parsed.ok) return fail(parsed.reason, "connection_url");
    hostname = parsed.hostname;
    port = parsed.port;
    database = parsed.database;
    username = parsed.username;
    sslmode = parsed.sslmode;
    sslRequired = parsed.ssl_required;
    classification = hostname === APPROVED_DISPOSABLE_POOLER_HOST
      ? "approved_session_pooler"
      : hostname === APPROVED_DISPOSABLE_HOST
        ? "approved_direct_host"
        : "unknown";
    credentialSource = credentialSource || `env:${DB_PASSWORD_ENV}`;
  }

  if (hostname == null && port == null && database == null && username == null) {
    hostname = APPROVED_DISPOSABLE_POOLER_HOST;
    port = APPROVED_DISPOSABLE_POOLER_PORT;
    database = APPROVED_DISPOSABLE_DATABASE;
    username = APPROVED_DISPOSABLE_POOLER_USER;
    sslmode = "require";
    sslRequired = true;
    classification = "approved_session_pooler";
    credentialSource = credentialSource || `env:${DB_PASSWORD_ENV}`;
  }

  const projectRef = input.project_ref || APPROVED_DISPOSABLE_PROJECT_REF;
  const projectName = input.project_name || APPROVED_DISPOSABLE_PROJECT_NAME;
  const orgId = input.org_id || APPROVED_DISPOSABLE_ORG_ID;
  if (input.project_ref && input.project_ref !== APPROVED_DISPOSABLE_PROJECT_REF) {
    return fail("caller-supplied identity not tracing to validated connection", "caller_identity");
  }
  if (input.project_name && input.project_name !== APPROVED_DISPOSABLE_PROJECT_NAME) {
    return fail("caller-supplied identity not tracing to validated connection", "caller_identity");
  }
  if (input.org_id && input.org_id !== APPROVED_DISPOSABLE_ORG_ID) {
    return fail("caller-supplied identity not tracing to validated connection", "caller_identity");
  }
  if (input.expected_live_role && input.expected_live_role !== APPROVED_DISPOSABLE_USER) {
    return fail("caller-supplied identity not tracing to validated connection", "caller_identity");
  }
  if (input.expected_live_database && input.expected_live_database !== APPROVED_DISPOSABLE_DATABASE) {
    return fail("caller-supplied identity not tracing to validated connection", "caller_identity");
  }

  const allowlist = validateConnectionAgainstDisposableAllowlist({
    hostname,
    port,
    database,
    username,
    sslmode,
    ssl_required: sslRequired === true || sslmode === "require",
    host_classification: classification || "approved_session_pooler",
    project_ref: projectRef,
    project_name: projectName,
    org_id: orgId,
  });
  if (!allowlist.ok) return fail(allowlist.reason, allowlist.parser_verdict);

  const mapping = allowlist.mapping;
  const fields = {
    project_ref: APPROVED_DISPOSABLE_PROJECT_REF,
    project_name: APPROVED_DISPOSABLE_PROJECT_NAME,
    org_id: APPROVED_DISPOSABLE_ORG_ID,
    identity_hostname_pin: APPROVED_DISPOSABLE_HOST,
    connection_hostname: String(hostname),
    connection_port: Number(port),
    connection_database: String(database),
    connection_username: String(username),
    expected_live_database: mapping.expected_live_current_database,
    expected_live_role: mapping.expected_live_current_user,
    host_classification: classification || "approved_session_pooler",
    ssl_required: true,
    sslmode: "require",
    credential_source: String(credentialSource || `env:${DB_PASSWORD_ENV}`),
    production_ref_rejected: true,
    production_ref: PRODUCTION_REF,
    pooler_username_mapping: { ...APPROVED_SESSION_POOLER_USERNAME_MAPPING },
    provenance: { ...FROZEN_TARGET_FIELD_PROVENANCE },
    source: String(input.source || "connection_metadata"),
  };
  fields.immutable_hash = hashFrozenTargetFields(fields);
  const target = deepFreeze(fields);
  return { ok: true, target, allowlist };
}

export function assertFrozenTargetUnmutated(target) {
  const fail = (reason, parser_verdict = "frozen_target_mutation") => ({
    ok: false,
    reason,
    parser_verdict,
    hold: IMMUTABLE_TARGET_HOLD,
    dbAccess: false,
    dbPushCalls: 0,
    repairCalls: 0,
    continuationCalls: 0,
  });
  if (target == null || typeof target !== "object" || Array.isArray(target)) {
    return fail("frozen target missing", "target_missing");
  }
  if (!Object.isFrozen(target)) {
    return fail("frozen target mutation", "frozen_target_mutation");
  }
  const actual = hashFrozenTargetFields(target);
  if (!target.immutable_hash || actual !== target.immutable_hash) {
    return fail("frozen target mutation", "frozen_target_mutation");
  }
  const allowlist = validateConnectionAgainstDisposableAllowlist({
    hostname: target.connection_hostname,
    port: target.connection_port,
    database: target.connection_database,
    username: target.connection_username,
    sslmode: target.sslmode,
    ssl_required: target.ssl_required,
    host_classification: target.host_classification,
    project_ref: target.project_ref,
    project_name: target.project_name,
    org_id: target.org_id,
  });
  if (!allowlist.ok) return fail(allowlist.reason, allowlist.parser_verdict);
  return { ok: true, target };
}

export function compareLiveIdentityToFrozenTarget({ live = {}, frozenTarget } = {}) {
  const fail = (reason, parser_verdict) => ({
    ok: false,
    reason,
    parser_verdict,
    hold: FINAL_POISON_ABSENCE_HOLD,
    live,
    frozenTarget,
  });
  const frozen = assertFrozenTargetUnmutated(frozenTarget);
  if (!frozen.ok) return frozen;
  const db = live.current_database;
  const role = live.current_user;
  if (db == null) return fail("null live current_database", "null_database");
  if (role == null) return fail("null live current_user", "null_user");
  if (db === "") return fail("empty live current_database", "empty_database");
  if (role === "") return fail("empty live current_user", "empty_user");
  if (typeof db !== "string") return fail("live current_database wrong type", "wrong_type");
  if (typeof role !== "string") return fail("live current_user wrong type", "wrong_type");
  if (db !== frozenTarget.expected_live_database) {
    return fail("mismatched live DB vs frozen expected DB", "wrong_database");
  }
  if (db !== frozenTarget.connection_database) {
    return fail("mismatched live DB vs connection database", "wrong_database");
  }
  if (role !== frozenTarget.expected_live_role) {
    return fail("mismatched live role vs frozen expected role", "wrong_user");
  }
  if (role !== frozenTarget.pooler_username_mapping.expected_live_current_user) {
    return fail("mismatched live role vs username mapping", "username_mapping");
  }
  if (frozenTarget.connection_username !== frozenTarget.pooler_username_mapping.connection_username) {
    return fail("connection username mapping drifted", "username_mapping");
  }
  if (frozenTarget.project_ref !== frozenTarget.pooler_username_mapping.project_ref) {
    return fail("project ref does not match username mapping", "wrong_ref");
  }
  if (frozenTarget.ssl_required !== true || frozenTarget.sslmode !== "require") {
    return fail("missing SSL", "missing_ssl");
  }
  return {
    ok: true,
    live: Object.freeze({
      current_database: db,
      current_user: role,
      provenance: "original_query_output",
    }),
    frozenTarget,
  };
}

function exactPoisonEnvelopeFromOriginal(row) {
  if (row == null || typeof row !== "object" || Array.isArray(row)) {
    return { ok: false, reason: "envelope is not an object", parser_verdict: "array_not_object" };
  }
  const keys = Object.keys(row).sort();
  const required = [...FINAL_POISON_REQUIRED_KEYS].sort();
  if (keys.length !== required.length || keys.some((key, i) => key !== required[i])) {
    const extra = keys.filter((key) => !required.includes(key));
    const missing = required.filter((key) => !keys.includes(key));
    const verdict = extra.length === 0 && missing.length > 0
      ? "required_key_subset"
      : "keyset_mismatch";
    return {
      ok: false,
      reason: extra.length
        ? `final poison probe extra key ${extra[0]}`
        : "final poison probe missing required keys",
      parser_verdict: verdict,
      extraKeys: extra,
      missingKeys: missing,
    };
  }
  if (row.schema_version !== FINAL_POISON_SCHEMA_VERSION) {
    return { ok: false, reason: "unknown schema version", parser_verdict: "unknown_schema_version" };
  }
  if (row.probe_marker !== POISON_PROBE_MARKER) {
    return { ok: false, reason: "unknown probe marker", parser_verdict: "probe_marker" };
  }
  if (typeof row.poisonPresent !== "boolean") {
    return { ok: false, reason: "poisonPresent is not an explicit boolean", parser_verdict: "wrong_type" };
  }
  if (row.current_database == null) {
    return { ok: false, reason: "null live current_database", parser_verdict: "null_database" };
  }
  if (row.current_user == null) {
    return { ok: false, reason: "null live current_user", parser_verdict: "null_user" };
  }
  if (row.current_database === "") {
    return { ok: false, reason: "empty live current_database", parser_verdict: "empty_database" };
  }
  if (row.current_user === "") {
    return { ok: false, reason: "empty live current_user", parser_verdict: "empty_user" };
  }
  if (typeof row.current_database !== "string") {
    return { ok: false, reason: "current_database wrong type", parser_verdict: "wrong_type" };
  }
  if (typeof row.current_user !== "string") {
    return { ok: false, reason: "current_user wrong type", parser_verdict: "wrong_type" };
  }
  return { ok: true, row };
}

/**
 * Strict original-process-result poison verifier.
 * Validates the actual child-process result + original stdout.
 * Never reconstructs a replacement JSON envelope.
 */
export function evaluateOriginalPoisonProcessResult(result, { frozenTarget } = {}) {
  const fail = (reason, extra = {}) => ({
    ok: false,
    absent: false,
    poisonPresent: extra.poisonPresent ?? null,
    hold: extra.hold || FINAL_POISON_ABSENCE_HOLD,
    reason,
    parser_verdict: extra.parser_verdict || "rejected",
    poison_absence_verdict: "not_proven",
    usedFallbackParser: false,
    reconstructedPoisonObject: extra.reconstructedPoisonObject === true,
    raw: extra.raw || null,
    parseResult: extra.parseResult || { ok: false, reason },
    validationResult: extra.validationResult || { ok: false, reason },
    live: extra.live || null,
    frozenTarget: extra.frozenTarget || frozenTarget || null,
    repairCalls: 0,
    dbPushCalls: extra.dbPushCalls ?? 0,
    continuationCalls: 0,
  });

  const contract = evaluateOriginalProcessResultContract(result);
  if (!contract.ok) {
    return fail(contract.reason, { parser_verdict: contract.parser_verdict });
  }
  const parsed = parseExactOriginalJsonObject(result);
  if (!parsed.ok) {
    return fail(parsed.reason, {
      parser_verdict: parsed.parser_verdict,
      raw: parsed.raw,
      parseResult: parsed.parseResult,
      reconstructedPoisonObject: parsed.parser_verdict === "reconstructed_not_original",
    });
  }
  const envelope = exactPoisonEnvelopeFromOriginal(parsed.value);
  if (!envelope.ok) {
    return fail(envelope.reason, {
      parser_verdict: envelope.parser_verdict,
      raw: parsed.raw,
      parseResult: parsed.parseResult,
      validationResult: envelope,
      extraKeys: envelope.extraKeys,
      missingKeys: envelope.missingKeys,
    });
  }
  const targetCheck = frozenTarget
    ? assertFrozenTargetUnmutated(frozenTarget)
    : constructImmutableValidatedTargetFromConnection({ source: "poison-default-connection" });
  if (!targetCheck.ok) {
    return fail(targetCheck.reason, {
      parser_verdict: targetCheck.parser_verdict,
      raw: parsed.raw,
      parseResult: parsed.parseResult,
      validationResult: targetCheck,
      hold: targetCheck.hold || IMMUTABLE_TARGET_HOLD,
      frozenTarget,
    });
  }
  const bound = targetCheck.target;
  const compared = compareLiveIdentityToFrozenTarget({
    live: {
      current_database: envelope.row.current_database,
      current_user: envelope.row.current_user,
    },
    frozenTarget: bound,
  });
  if (!compared.ok) {
    return fail(compared.reason, {
      parser_verdict: compared.parser_verdict,
      raw: parsed.raw,
      parseResult: parsed.parseResult,
      validationResult: compared,
      live: {
        current_database: envelope.row.current_database,
        current_user: envelope.row.current_user,
        provenance: "original_query_output",
      },
      frozenTarget: bound,
    });
  }
  if (envelope.row.poisonPresent !== false) {
    return fail("poisonPresent true", {
      parser_verdict: "poison_present",
      poisonPresent: true,
      raw: parsed.raw,
      parseResult: parsed.parseResult,
      validationResult: { ok: false, reason: "poisonPresent true" },
      live: compared.live,
      frozenTarget: bound,
    });
  }
  return {
    ok: true,
    absent: true,
    poisonPresent: false,
    parser_verdict: "valid_json_exact_schema",
    poison_absence_verdict: "proven_absent",
    usedFallbackParser: false,
    reconstructedPoisonObject: false,
    row: envelope.row,
    live: compared.live,
    frozenTarget: bound,
    raw: parsed.raw,
    parseResult: parsed.parseResult,
    validationResult: { ok: true, envelope: envelope.row, identity: compared.live },
    repairCalls: 0,
    dbPushCalls: 0,
    continuationCalls: 0,
  };
}

export function evaluatePoisonAbsent(result, options = {}) {
  const evaluated = evaluateOriginalPoisonProcessResult(result, options);
  return {
    ...evaluated,
    absent: evaluated.ok === true && evaluated.absent === true,
  };
}

export function evaluateFinalPoisonAbsence(result, options = {}) {
  return evaluateOriginalPoisonProcessResult(result, options);
}

export function evaluatePoisonTargetIdentity(target) {
  if (target && target.immutable_hash) {
    return assertFrozenTargetUnmutated(target);
  }
  return constructImmutableValidatedTargetFromConnection({
    connection: target && typeof target === "object" ? {
      hostname: target.connection_hostname || target.hostname,
      port: target.connection_port || target.port,
      database: target.connection_database || target.database_name || target.database,
      username: target.connection_username || target.pooler_identity || target.username,
      sslmode: target.sslmode,
      ssl_required: target.ssl_required,
      host_classification: target.host_classification || target.connection_mode,
      credential_source: target.credential_source,
    } : undefined,
    project_ref: target?.project_ref,
    project_name: target?.project_name,
    org_id: target?.org_id,
    source: "evaluatePoisonTargetIdentity",
  });
}

export function bindPoisonTargetIdentity(input = {}) {
  if (input.frozenTarget) {
    const checked = assertFrozenTargetUnmutated(input.frozenTarget);
    if (!checked.ok) return { ...checked, target_identity: null };
    return { ok: true, target: checked.target, target_identity: checked.target };
  }
  const constructed = constructImmutableValidatedTargetFromConnection({
    connection: input.connection,
    connectionUrl: input.connectionUrl,
    project_ref: input.project_ref || input.live?.project_ref,
    project_name: input.project_name,
    org_id: input.org_id,
    source: input.source || "bindPoisonTargetIdentity",
  });
  if (!constructed.ok) return { ...constructed, target_identity: null };
  if (input.live && (input.live.current_database != null || input.live.current_user != null)) {
    const compared = compareLiveIdentityToFrozenTarget({
      live: input.live,
      frozenTarget: constructed.target,
    });
    if (!compared.ok) return { ...compared, target: constructed.target, target_identity: constructed.target };
  }
  return { ok: true, target: constructed.target, target_identity: constructed.target };
}

/**
 * Test / evidence helper. Assembling a row is NOT original stdout.
 * Passing the assembled object as process stdout without preservation
 * stamps is rejected by the strict verifier when marked reconstructed.
 */
export function assembleFinalPoisonExactRow({
  poisonPresent = false,
  current_database = APPROVED_DISPOSABLE_DATABASE,
  current_user = APPROVED_DISPOSABLE_USER,
  probe_marker = POISON_PROBE_MARKER,
  schema_version = FINAL_POISON_SCHEMA_VERSION,
} = {}) {
  return {
    schema_version,
    poisonPresent,
    current_database,
    current_user,
    probe_marker,
  };
}

export function originalPoisonProcessResult(overrides = {}) {
  const row = assembleFinalPoisonExactRow(overrides.row || {});
  const stdout = `${JSON.stringify(row)}\n`;
  const hashed = createHash("sha256").update(stdout, "utf8").digest("hex");
  return preserveOriginalProcessStdout({
    status: 0,
    stdout,
    stderr: "",
    signal: null,
    timeout: false,
    originalStdout: stdout,
    originalStdoutSha256: hashed,
    originalStdoutByteLength: Buffer.byteLength(stdout),
    stdoutPreservedBeforeTransform: true,
    ...(overrides.result || {}),
  }).preserved;
}

export function poisonAbsentFromProbe(result) {
  return evaluatePoisonAbsent(result).absent === true;
}

/**
 * Isolated read-only psql transport for poison-absence queries only.
 * Migration runner remains supabase db push CLI 2.117.0. Repair remains
 * version-pinned CLI repair. Password never on argv / logs / evidence.
 */
export const PSQL_POISON_QUERY_ARGV = Object.freeze([
  "-X",
  "-q",
  "-t",
  "-A",
  "-w",
  "-v",
  "ON_ERROR_STOP=1",
]);

export const PSQL_POISON_ISOLATED_ENV_KEYS = Object.freeze([
  "PGHOST",
  "PGPORT",
  "PGDATABASE",
  "PGUSER",
  "PGPASSWORD",
  "PGSSLMODE",
  "PGCONNECT_TIMEOUT",
  "PATH",
  "HOME",
]);

export const PSQL_POISON_CONNECT_TIMEOUT_SECONDS = "15";

/**
 * No local PostgreSQL 17 / psql in this cloud-agent image. Framing is
 * unit-tested against the exact byte contract. Chief box has
 * docker postgres:17.6 — live proof remains required there.
 */
export const MUST_LOCAL_PSQL_PROOF_ON_17_6 = true;

let poisonPsqlSpawnImpl = spawnSync;

export function __installPoisonPsqlSpawnForTests(fn) {
  poisonPsqlSpawnImpl = typeof fn === "function" ? fn : spawnSync;
}

export function __resetPoisonPsqlSpawnForTests() {
  poisonPsqlSpawnImpl = spawnSync;
}

function failPoisonPsqlBeforeSpawn(reason, parser_verdict = "target_rejected") {
  return {
    ok: false,
    spawned: false,
    reason,
    parser_verdict,
    hold: IMMUTABLE_TARGET_HOLD,
    status: 1,
    stdout: "",
    stderr: "",
    signal: null,
    timeout: false,
    spawnError: reason,
    queryError: reason,
    psqlVersion: null,
    argv: null,
    envKeys: null,
    repairCalls: 0,
    dbPushCalls: 0,
    continuationCalls: 0,
  };
}

function resolvePsqlBinaryDir() {
  const search = process.env.PATH || "/usr/bin:/bin:/usr/local/bin";
  for (const dir of search.split(path.delimiter)) {
    if (!dir) continue;
    const candidate = path.join(dir, "psql");
    try {
      if (fs.existsSync(candidate)) return dir;
    } catch {
      // continue
    }
  }
  return ["/usr/bin", "/bin"].join(path.delimiter);
}

function assertPoisonPsqlArgvSafe(args, password) {
  const list = Array.isArray(args) ? args.map((a) => String(a)) : [];
  if (list.some((a) => a === "-d" || a === "--dbname" || a.startsWith("postgresql://") || a.startsWith("postgres://"))) {
    return { ok: false, reason: "poison psql must not take a URL on argv" };
  }
  if (list.some((a) => a === "-p" || a === "--password" || a === "-W")) {
    return { ok: false, reason: "poison psql must not take password/port flags on argv" };
  }
  if (password && list.some((a) => a.includes(password))) {
    return { ok: false, reason: "poison psql argv leaked password" };
  }
  return { ok: true, args: list };
}

export function readInstalledPsqlVersion() {
  const dir = resolvePsqlBinaryDir();
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "f3-poison-psql-ver-"));
  try {
    const child = poisonPsqlSpawnImpl("psql", ["--version"], {
      encoding: "utf8",
      env: { PATH: dir, HOME: home },
      timeout: 5000,
      windowsHide: true,
    });
    if (child.error && child.error.code !== "ETIMEDOUT") {
      return { ok: false, version: null, reason: child.error.message || "psql version spawn error" };
    }
    if (child.status !== 0) {
      return { ok: false, version: null, reason: "psql --version nonzero" };
    }
    return { ok: true, version: String(child.stdout || "").trim() };
  } finally {
    try {
      fs.rmSync(home, { recursive: true, force: true });
    } catch {
      // ignore
    }
  }
}

export function validatePoisonPsqlTargetBeforeSpawn(frozenTarget) {
  const frozen = assertFrozenTargetUnmutated(frozenTarget);
  if (!frozen.ok) return frozen;
  const t = frozen.target;
  if (t.credential_source !== `env:${DB_PASSWORD_ENV}`) {
    return failPoisonPsqlBeforeSpawn("credential source not frozen env password", "credential_source");
  }
  if (t.ssl_required !== true || t.sslmode !== "require") {
    return failPoisonPsqlBeforeSpawn("missing SSL", "missing_ssl");
  }
  if (
    t.connection_hostname !== APPROVED_DISPOSABLE_POOLER_HOST
    && t.connection_hostname !== APPROVED_DISPOSABLE_HOST
  ) {
    return failPoisonPsqlBeforeSpawn("wrong/aliased hostname", "wrong_hostname");
  }
  if (
    t.connection_port !== APPROVED_DISPOSABLE_POOLER_PORT
    && t.connection_port !== APPROVED_DISPOSABLE_PORT
  ) {
    return failPoisonPsqlBeforeSpawn("wrong port", "wrong_port");
  }
  if (t.connection_database !== APPROVED_DISPOSABLE_DATABASE) {
    return failPoisonPsqlBeforeSpawn("wrong database", "wrong_database");
  }
  if (
    t.connection_username !== APPROVED_DISPOSABLE_POOLER_USER
    && t.connection_username !== APPROVED_DISPOSABLE_USER
  ) {
    return failPoisonPsqlBeforeSpawn("wrong username", "wrong_username");
  }
  if (t.project_ref !== APPROVED_DISPOSABLE_PROJECT_REF) {
    return failPoisonPsqlBeforeSpawn("wrong ref", "wrong_ref");
  }
  if (t.org_id !== APPROVED_DISPOSABLE_ORG_ID) {
    return failPoisonPsqlBeforeSpawn("wrong org", "wrong_org");
  }
  if (t.pooler_username_mapping.connection_username !== APPROVED_DISPOSABLE_POOLER_USER) {
    return failPoisonPsqlBeforeSpawn("connection username mapping drifted", "username_mapping");
  }
  if (t.pooler_username_mapping.expected_live_current_user !== APPROVED_DISPOSABLE_USER) {
    return failPoisonPsqlBeforeSpawn("username mapping role mismatch", "username_mapping");
  }
  if (t.pooler_username_mapping.project_ref !== APPROVED_DISPOSABLE_PROJECT_REF) {
    return failPoisonPsqlBeforeSpawn("project ref does not match username mapping", "wrong_ref");
  }
  const password = process.env[DB_PASSWORD_ENV];
  if (password == null || String(password) === "") {
    return failPoisonPsqlBeforeSpawn("frozen credential env password missing", "credential_source");
  }
  return { ok: true, target: t, password: String(password) };
}

export function buildIsolatedPoisonPsqlEnv(frozenTarget) {
  const validated = validatePoisonPsqlTargetBeforeSpawn(frozenTarget);
  if (!validated.ok) return validated;
  const t = validated.target;
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "f3-poison-psql-home-"));
  const env = Object.create(null);
  env.PGHOST = t.connection_hostname;
  env.PGPORT = String(t.connection_port);
  env.PGDATABASE = t.connection_database;
  env.PGUSER = t.connection_username;
  env.PGPASSWORD = validated.password;
  env.PGSSLMODE = t.sslmode;
  env.PGCONNECT_TIMEOUT = PSQL_POISON_CONNECT_TIMEOUT_SECONDS;
  env.PATH = resolvePsqlBinaryDir();
  env.HOME = home;
  const keys = Object.keys(env).sort();
  const allowed = [...PSQL_POISON_ISOLATED_ENV_KEYS].sort();
  if (keys.length !== allowed.length || keys.some((key, i) => key !== allowed[i])) {
    try {
      fs.rmSync(home, { recursive: true, force: true });
    } catch {
      // ignore
    }
    return failPoisonPsqlBeforeSpawn("isolated psql env key set drifted", "env_keys");
  }
  if (env.DATABASE_URL || env.DIRECT_URL || env.SUPABASE_ACCESS_TOKEN || env.PGURL) {
    return failPoisonPsqlBeforeSpawn("isolated psql env inherited forbidden keys", "env_keys");
  }
  return { ok: true, env, home, target: t };
}

export function runIsolatedPoisonPsqlQuery({ frozenTarget, sql } = {}) {
  const validated = validatePoisonPsqlTargetBeforeSpawn(frozenTarget);
  if (!validated.ok) return validated;
  if (typeof sql !== "string" || sql.trim() === "") {
    return failPoisonPsqlBeforeSpawn("poison psql SQL missing", "query_error");
  }
  const envBuilt = buildIsolatedPoisonPsqlEnv(frozenTarget);
  if (!envBuilt.ok) return envBuilt;
  const args = [...PSQL_POISON_QUERY_ARGV, "-c", sql];
  const argvSafe = assertPoisonPsqlArgvSafe(args, envBuilt.env.PGPASSWORD);
  if (!argvSafe.ok) {
    try {
      fs.rmSync(envBuilt.home, { recursive: true, force: true });
    } catch {
      // ignore
    }
    return failPoisonPsqlBeforeSpawn(argvSafe.reason, "argv");
  }
  let psqlVersion = null;
  try {
    const versionProbe = readInstalledPsqlVersion();
    psqlVersion = versionProbe.ok ? versionProbe.version : null;
    if (!versionProbe.ok) {
      return {
        ...failPoisonPsqlBeforeSpawn(versionProbe.reason || "psql version probe failed", "spawn_error"),
        psqlVersion: null,
      };
    }
    const child = poisonPsqlSpawnImpl("psql", args, {
      encoding: "utf8",
      env: envBuilt.env,
      timeout: Number(PSQL_POISON_CONNECT_TIMEOUT_SECONDS) * 1000,
      maxBuffer: 1024 * 1024,
      windowsHide: true,
    });
    const timeout = child.error?.code === "ETIMEDOUT"
      || child.timeout === true
      || child.timedOut === true;
    const spawnError = child.error && child.error.code !== "ETIMEDOUT"
      ? child.error
      : null;
    return {
      status: child.status,
      signal: child.signal ?? child.signalCode ?? null,
      stdout: child.stdout ?? "",
      stderr: child.stderr ?? "",
      timeout,
      spawnError,
      killed: child.killed === true,
      queryError: null,
      psqlVersion,
      argv: args,
      envKeys: Object.keys(envBuilt.env).sort(),
      transport: "isolated-psql",
      spawned: true,
    };
  } finally {
    try {
      fs.rmSync(envBuilt.home, { recursive: true, force: true });
    } catch {
      // ignore
    }
  }
}

export function evaluateCleanupProven(result) {
  if (result == null || typeof result !== "object" || Array.isArray(result)) {
    return { ok: false, reason: "cleanup result missing or not an object" };
  }
  if (!Object.prototype.hasOwnProperty.call(result, "status") || result.status !== 0) {
    return { ok: false, reason: `cleanup status ${result.status}` };
  }
  const blob = textOf(result);
  if (hasSqlFailureOutput(blob)) {
    return { ok: false, reason: "cleanup output contains SQL error", errors: extractSqlFailureLines(blob) };
  }
  return { ok: true };
}

export function authorizedStagedFilename(file) {
  if (!F3_FORWARD_FILES.includes(file)) {
    throw new Error(`HOLD: ${file} is not an authorized F3 forward file`);
  }
  return timestampFilenameFor(file);
}

export function authorizedPrefixFilesThrough(throughFile) {
  const idx = F3_FORWARD_FILES.indexOf(throughFile);
  if (idx < 0) {
    throw new Error(`HOLD: ${throughFile} is not an authorized F3 forward file`);
  }
  return F3_FORWARD_FILES.slice(0, idx + 1);
}

export function authorizedStagedPrefixThrough(throughFile) {
  return authorizedPrefixFilesThrough(throughFile).map((file) => timestampFilenameFor(file));
}

export function expectedAppliedPrefixFiles(throughFile, phase = "initial") {
  const idx = F3_FORWARD_FILES.indexOf(throughFile);
  if (idx < 0) {
    throw new Error(`HOLD: ${throughFile} is not an authorized F3 forward file`);
  }
  if (phase === "retry") return F3_FORWARD_FILES.slice(0, idx + 1);
  return F3_FORWARD_FILES.slice(0, idx);
}

export function expectedPendingFiles(throughFile, phase = "initial") {
  if (phase === "retry") return [];
  if (!F3_FORWARD_FILES.includes(throughFile)) {
    throw new Error(`HOLD: ${throughFile} is not an authorized F3 forward file`);
  }
  return [throughFile];
}

export function listIsolatedMigrationFilenames(workdir) {
  const migDir = path.join(workdir, "supabase", "migrations");
  if (!fs.existsSync(migDir)) return [];
  return fs.readdirSync(migDir).sort();
}

function isolatedMigrationsDir(workdir) {
  return path.join(workdir, "supabase", "migrations");
}

function copyAuthorizedSourceToDest(isolated, sourceFile, dest) {
  const intended = timestampFilenameFor(sourceFile);
  const copy = (isolated?.copies || []).find((c) => c.destName === intended);
  const srcFile = copy?.sourceFile || sourceFile;
  const src = path.join(repoRoot, "supabase", "migrations", srcFile);
  if (!fs.existsSync(src)) {
    throw new Error(`HOLD: authorized source missing for ${srcFile}`);
  }
  fs.writeFileSync(dest, fs.readFileSync(src));
}

/**
 * PREFIX-COMPLETE, SINGLE-PENDING staging.
 * Stage every authorized F3 timestamp file through `throughFile` (inclusive).
 * Later F3 files are removed. Unexpected files block.
 * Repository migration bytes are never rewritten.
 */
export function syncIsolatedMigrationsThrough(isolated, throughFile) {
  if (!isolated?.workdir) {
    throw new Error("HOLD: isolated workdir required for staging");
  }
  const intended = authorizedStagedPrefixThrough(throughFile);
  const intendedSet = new Set(intended);
  const authorized = new Set(F3_FORWARD_FILES.map((f) => timestampFilenameFor(f)));
  const migDir = isolatedMigrationsDir(isolated.workdir);
  if (!fs.existsSync(migDir)) {
    throw new Error("HOLD: isolated migrations directory missing");
  }

  const names = fs.readdirSync(migDir);
  const unexpected = names.filter((name) => !authorized.has(name));
  if (unexpected.length > 0) {
    const err = new Error(
      `HOLD: unexpected isolated migration files block execution: ${unexpected.join(",")}`,
    );
    err.code = "F3_DBPUSH_STAGING_UNEXPECTED_FILES";
    throw err;
  }

  for (const name of names) {
    if (!intendedSet.has(name)) {
      fs.rmSync(path.join(migDir, name), { force: true });
    }
  }

  for (const sourceFile of authorizedPrefixFilesThrough(throughFile)) {
    const destName = timestampFilenameFor(sourceFile);
    const dest = path.join(migDir, destName);
    if (!fs.existsSync(dest)) {
      copyAuthorizedSourceToDest(isolated, sourceFile, dest);
    }
  }

  const staged = fs.readdirSync(migDir).filter((name) => name.endsWith(".sql")).sort();
  const expected = [...intended].sort();
  if (staged.length !== expected.length || expected.some((name, i) => staged[i] !== name)) {
    const err = new Error(
      `HOLD: staging did not leave prefix-complete set through ${throughFile}: ${staged.join(",")}`,
    );
    err.code = "F3_DBPUSH_STAGING_INEXACT";
    throw err;
  }
  return staged;
}

export const stagePrefixCompleteThrough = syncIsolatedMigrationsThrough;

function failPreflight(code, reason, extra = {}) {
  return { ok: false, code, reason, ...extra };
}

function unwrapHistoryRows(value) {
  let current = value;
  if (typeof current === "string") {
    try {
      current = JSON.parse(current);
    } catch {
      return { ok: false, reason: "malformed history response: non-JSON row payload", code: "malformed_history" };
    }
  }
  if (Array.isArray(current)) {
    if (
      current.length === 1 &&
      current[0] &&
      typeof current[0] === "object" &&
      !Array.isArray(current[0]) &&
      (Array.isArray(current[0].json_agg) || Array.isArray(current[0].coalesce) || Array.isArray(current[0].rows))
    ) {
      current = current[0].json_agg || current[0].coalesce || current[0].rows;
    } else if (
      current.length === 1 &&
      typeof current[0] === "string"
    ) {
      return unwrapHistoryRows(current[0]);
    }
    return { ok: true, rows: current };
  }
  if (current && typeof current === "object") {
    const unexpected = Object.keys(current).filter(
      (k) => !["json_agg", "coalesce", "rows", "advisory", "warning"].includes(k),
    );
    if (unexpected.length > 0 && !Array.isArray(current.json_agg) && !Array.isArray(current.coalesce) && !Array.isArray(current.rows)) {
      return { ok: false, reason: "malformed history response: unexpected object keys", code: "malformed_history" };
    }
    if (Array.isArray(current.json_agg)) return { ok: true, rows: current.json_agg };
    if (Array.isArray(current.coalesce)) return { ok: true, rows: current.coalesce };
    if (Array.isArray(current.rows)) return { ok: true, rows: current.rows };
    return { ok: false, reason: "malformed history response: missing rows", code: "malformed_history" };
  }
  return { ok: false, reason: "malformed history response: wrong JSON shape", code: "malformed_history" };
}

export function parseRemoteMigrationHistoryResult(result) {
  if (result == null || typeof result !== "object" || Array.isArray(result)) {
    return failPreflight("malformed_history", "malformed history response");
  }
  if (!Object.prototype.hasOwnProperty.call(result, "status") || result.status !== 0) {
    return failPreflight(
      "history_nonzero",
      `history query exits nonzero: status=${result.status}`,
      { status: result.status },
    );
  }
  const blob = textOf(result);
  if (hasSqlFailureOutput(blob)) {
    return failPreflight("malformed_history", "malformed history response: SQL error");
  }
  const parsedStdout = parseEntireJson(result.stdout);
  if (!parsedStdout.ok) {
    return failPreflight("malformed_history", `malformed history response: ${parsedStdout.reason}`);
  }
  const unwrapped = unwrapHistoryRows(parsedStdout.value);
  if (!unwrapped.ok) return unwrapped;
  if (!Array.isArray(unwrapped.rows)) {
    return failPreflight("malformed_history", "malformed history response: rows are not an array");
  }

  const rows = [];
  const seen = new Set();
  for (const row of unwrapped.rows) {
    if (!row || typeof row !== "object" || Array.isArray(row)) {
      return failPreflight("malformed_history", "malformed history response: row is not an object");
    }
    const version = row.version;
    const name = row.name;
    if (typeof version !== "string" || !/^\d{14}$/.test(version)) {
      return failPreflight("malformed_history", "malformed history response: invalid version");
    }
    if (typeof name !== "string") {
      return failPreflight("malformed_history", "malformed history response: invalid name");
    }
    if (seen.has(version)) {
      return failPreflight("remote_duplicate", `duplicate remote version ${version}`);
    }
    seen.add(version);
    rows.push({ version, name });
  }
  return { ok: true, rows };
}

function inspectLocalStagedMigrations(workdir) {
  const migDir = isolatedMigrationsDir(workdir);
  if (!fs.existsSync(migDir)) {
    return failPreflight("local_missing_dir", "isolated migrations directory missing");
  }
  const names = fs.readdirSync(migDir);
  const sqlFiles = names.filter((name) => name.endsWith(".sql")).sort();
  const authorizedFilenames = new Set(F3_FORWARD_FILES.map((file) => timestampFilenameFor(file)));
  const versionToFiles = new Map();
  const unrelated = [];
  const parsed = [];

  for (const filename of sqlFiles) {
    const match = filename.match(/^(\d{14})_(.+)\.sql$/);
    if (!match) {
      unrelated.push(filename);
      continue;
    }
    const version = match[1];
    const historyName = match[2];
    if (!versionToFiles.has(version)) versionToFiles.set(version, []);
    versionToFiles.get(version).push(filename);
    const sourceFile = sourceFileForVersion(version);
    const authorizedName = sourceFile ? timestampFilenameFor(sourceFile) : null;
    const abs = path.join(migDir, filename);
    const digest = sha256Buffer(fs.readFileSync(abs));
    if (!authorizedFilenames.has(filename) && !sourceFile) {
      unrelated.push(filename);
    }
    parsed.push({
      filename,
      version,
      name: historyName,
      sourceFile,
      digest,
      authorizedFilename: filename === authorizedName,
    });
  }

  const duplicates = [...versionToFiles.entries()]
    .filter(([, files]) => files.length > 1)
    .map(([version, files]) => ({ version, files }));

  return { ok: true, sqlFiles, parsed, unrelated, duplicates, versionToFiles };
}

function evaluateRemoteAppliedPrefix(rows, expectedFiles) {
  const authorizedVersions = new Set(Object.values(PREASSIGNED_VERSIONS));
  const idxByVersion = new Map(F3_FORWARD_FILES.map((file, i) => [PREASSIGNED_VERSIONS[file], i]));

  for (const row of rows) {
    if (!authorizedVersions.has(row.version)) {
      return failPreflight("remote_unknown_version", `remote history unknown version ${row.version}`);
    }
    const file = sourceFileForVersion(row.version);
    if (!file || PREASSIGNED_NAMES[file] !== row.name) {
      return failPreflight(
        "remote_unexpected_name",
        `remote history unexpected name ${row.name} for ${row.version}`,
      );
    }
  }

  const indices = rows.map((row) => idxByVersion.get(row.version));
  for (let i = 1; i < indices.length; i += 1) {
    if (indices[i] <= indices[i - 1]) {
      return failPreflight("remote_out_of_order", "remote history out of order");
    }
    if (indices[i] !== indices[i - 1] + 1) {
      return failPreflight("remote_gap", "remote history gap");
    }
  }
  if (indices.length > 0 && indices[0] !== 0) {
    return failPreflight("remote_gap", "remote history gap");
  }

  return { ok: true };
}

function evaluateRemoteExactAppliedPrefix(rows, expectedFiles) {
  const expected = expectedFiles.map((file) => ({
    version: PREASSIGNED_VERSIONS[file],
    name: PREASSIGNED_NAMES[file],
  }));
  if (rows.length !== expected.length) {
    return failPreflight(
      "remote_applied_prefix_mismatch",
      "remote recorded versions/names do not equal expected applied prefix",
    );
  }
  for (let i = 0; i < expected.length; i += 1) {
    if (rows[i].version !== expected[i].version || rows[i].name !== expected[i].name) {
      return failPreflight(
        "remote_applied_prefix_mismatch",
        "remote recorded versions/names do not equal expected applied prefix",
      );
    }
  }
  return { ok: true, expected };
}

/**
 * Independently verify PREFIX-COMPLETE, SINGLE-PENDING staging before db push.
 * Expected prefix is computed from the frozen F3 map + current file + phase.
 * Never assigned from observed local or remote listings.
 */
export function evaluatePrefixCompleteSinglePendingStaging({
  workdir,
  currentFile,
  historyResult,
  cliVersion,
  phase = "initial",
} = {}) {
  if (cliVersion !== CLI_PIN) {
    return failPreflight("cli_pin", `cliVersion=${cliVersion} required=${CLI_PIN}`);
  }
  if (!F3_FORWARD_FILES.includes(currentFile)) {
    return failPreflight("unauthorized_file", `unknown file ${currentFile}`);
  }
  if (!workdir) {
    return failPreflight("workdir_missing", "isolated workdir required for staging preflight");
  }

  const expectedLocalFiles = authorizedPrefixFilesThrough(currentFile);
  const expectedLocalNames = authorizedStagedPrefixThrough(currentFile);
  const expectedApplied = expectedAppliedPrefixFiles(currentFile, phase);
  const expectedPending = expectedPendingFiles(currentFile, phase);
  const currentVersion = PREASSIGNED_VERSIONS[currentFile];
  const currentName = PREASSIGNED_NAMES[currentFile];
  const currentFilename = timestampFilenameFor(currentFile);
  const laterFiles = F3_FORWARD_FILES.slice(F3_FORWARD_FILES.indexOf(currentFile) + 1);

  const history = parseRemoteMigrationHistoryResult(historyResult);
  if (!history.ok) return history;

  const remoteStructure = evaluateRemoteAppliedPrefix(history.rows, expectedApplied);
  if (!remoteStructure.ok) return remoteStructure;

  const remoteVersionsEarly = history.rows.map((row) => row.version);
  if (phase === "initial" && remoteVersionsEarly.includes(currentVersion)) {
    return failPreflight(
      "current_already_remote",
      "current target already remotely recorded before initial push",
    );
  }

  const remotePrefix = evaluateRemoteExactAppliedPrefix(history.rows, expectedApplied);
  if (!remotePrefix.ok) return remotePrefix;

  const local = inspectLocalStagedMigrations(workdir);
  if (!local.ok) return local;

  if (local.duplicates.length > 0) {
    return failPreflight(
      "duplicate_timestamp",
      `duplicate timestamp exists: ${local.duplicates.map((d) => d.version).join(",")}`,
    );
  }
  if (local.unrelated.length > 0) {
    return failPreflight(
      "unrelated_migration",
      `unrelated migration file present: ${local.unrelated.join(",")}`,
    );
  }

  const laterPresent = local.parsed.filter((row) => laterFiles.some((file) => PREASSIGNED_VERSIONS[file] === row.version));
  if (laterPresent.length > 0) {
    return failPreflight(
      "later_migration_staged",
      `later F3 migration staged: ${laterPresent.map((row) => row.filename).join(",")}`,
    );
  }

  const localByVersion = new Map(local.parsed.map((row) => [row.version, row]));
  for (const file of expectedApplied) {
    const version = PREASSIGNED_VERSIONS[file];
    const row = localByVersion.get(version);
    if (!row) {
      return failPreflight(
        "applied_remote_missing_locally",
        `applied remote version ${version} missing from local workdir`,
      );
    }
    if (row.filename !== timestampFilenameFor(file) || row.name !== PREASSIGNED_NAMES[file]) {
      return failPreflight(
        "applied_local_identity",
        `applied local file wrong name or timestamp for ${file}: ${row.filename}`,
      );
    }
    if (row.digest !== FROZEN_DIGESTS[file]) {
      return failPreflight(
        "applied_local_digest",
        `applied local file wrong digest for ${file}`,
      );
    }
  }

  const currentLocal = localByVersion.get(currentVersion);
  if (phase === "initial" && !currentLocal) {
    return failPreflight("current_missing_locally", `current target ${currentFilename} missing locally`);
  }
  if (currentLocal) {
    if (currentLocal.filename !== currentFilename || currentLocal.name !== currentName) {
      return failPreflight(
        "current_local_identity",
        `current target wrong name or timestamp: ${currentLocal.filename}`,
      );
    }
    if (currentLocal.digest !== FROZEN_DIGESTS[currentFile]) {
      return failPreflight("current_local_digest", "current target does not match authorized digest");
    }
  }

  const remoteVersions = history.rows.map((row) => row.version);
  const localVersions = local.parsed.map((row) => row.version).sort();
  const remoteSet = new Set(remoteVersions);
  const localSet = new Set(localVersions);
  const pending = localVersions.filter((version) => !remoteSet.has(version));
  const remoteMinusLocal = remoteVersions.filter((version) => !localSet.has(version));
  const expectedPendingVersions = expectedPending.map((file) => PREASSIGNED_VERSIONS[file]);

  if (phase === "initial" && remoteSet.has(currentVersion)) {
    return failPreflight(
      "current_already_remote",
      "current target already remotely recorded before initial push",
    );
  }
  if (phase === "retry" && !remoteSet.has(currentVersion)) {
    return failPreflight(
      "current_missing_remote_after_repair",
      "current target absent from remote history before retry",
    );
  }

  if (pending.length !== expectedPendingVersions.length || pending.some((v, i) => v !== expectedPendingVersions[i])) {
    if (pending.length > 1 && phase === "initial") {
      return failPreflight(
        "two_unapplied",
        `local-minus-remote versions ${JSON.stringify(pending)} is not exactly [${currentVersion}]`,
      );
    }
    return failPreflight(
      "pending_mismatch",
      `local-minus-remote versions ${JSON.stringify(pending)} expected ${JSON.stringify(expectedPendingVersions)}`,
    );
  }
  if (remoteMinusLocal.length > 0) {
    return failPreflight(
      "remote_minus_local",
      `remote-minus-local versions is not empty: ${remoteMinusLocal.join(",")}`,
    );
  }

  const observedLocalNames = local.parsed.map((row) => row.filename).sort();
  if (
    observedLocalNames.length !== expectedLocalNames.length ||
    expectedLocalNames.some((name, i) => observedLocalNames[i] !== name)
  ) {
    return failPreflight(
      "local_prefix_mismatch",
      `local staged set ${JSON.stringify(observedLocalNames)} != prefix ${JSON.stringify(expectedLocalNames)}`,
    );
  }

  return {
    ok: true,
    phase,
    currentFile,
    currentVersion,
    staged: observedLocalNames,
    expectedLocal: expectedLocalFiles,
    expectedApplied,
    expectedPending,
    pending,
    remote: history.rows,
    productionHistoryLimitation: PRODUCTION_HISTORY_LIMITATION_WARNING,
  };
}

export function assertPrefixCompleteSinglePendingStaging(input = {}) {
  const result = evaluatePrefixCompleteSinglePendingStaging(input);
  if (!result.ok) {
    const err = new Error(`${PREFIX_COMPLETE_SINGLE_PENDING_HOLD}: ${result.reason}`);
    err.code = result.code || "F3_DBPUSH_STAGING_PREFLIGHT";
    err.preflight = result;
    throw err;
  }
  return result;
}

/**
 * Shared qualify/test orchestration: stage prefix-complete, independently
 * preflight, then maybe db-push. Repair is accepted only so callers can prove
 * it is not invoked when preflight fails.
 */
export async function runPrefixCompleteSinglePendingOrchestration({
  isolated,
  file,
  cliVersion,
  queryHistory,
  dbPush,
  repair,
  phase = "initial",
  stage = true,
} = {}) {
  let staged = null;
  try {
    if (stage) {
      staged = syncIsolatedMigrationsThrough(isolated, file);
    } else if (isolated?.workdir) {
      staged = listIsolatedMigrationFilenames(isolated.workdir).filter((name) => name.endsWith(".sql"));
    }
  } catch (err) {
    return {
      ok: false,
      staged,
      dbPushCalls: 0,
      repairCalls: 0,
      hold: PREFIX_COMPLETE_SINGLE_PENDING_HOLD,
      error: String(err?.message || err),
      code: err?.code || "F3_DBPUSH_STAGING_UNEXPECTED_FILES",
      preflight: err?.preflight || { ok: false, reason: String(err?.message || err), code: err?.code },
    };
  }

  let historyResult;
  try {
    if (typeof queryHistory !== "function") {
      return {
        ok: false,
        staged,
        dbPushCalls: 0,
        repairCalls: 0,
        hold: PREFIX_COMPLETE_SINGLE_PENDING_HOLD,
        preflight: failPreflight("history_query_missing", "history query callback missing"),
      };
    }
    historyResult = await Promise.resolve(queryHistory());
  } catch (err) {
    return {
      ok: false,
      staged,
      dbPushCalls: 0,
      repairCalls: 0,
      hold: PREFIX_COMPLETE_SINGLE_PENDING_HOLD,
      preflight: failPreflight("malformed_history", `malformed history response: ${err?.message || err}`),
    };
  }

  let preflight;
  try {
    preflight = assertPrefixCompleteSinglePendingStaging({
      workdir: isolated?.workdir,
      currentFile: file,
      historyResult,
      cliVersion,
      phase,
    });
  } catch (err) {
    return {
      ok: false,
      staged,
      dbPushCalls: 0,
      repairCalls: 0,
      hold: PREFIX_COMPLETE_SINGLE_PENDING_HOLD,
      preflight: err.preflight || { ok: false, reason: String(err?.message || err), code: err?.code },
    };
  }

  if (typeof dbPush !== "function") {
    return {
      ok: true,
      staged,
      preflight,
      dbPushCalls: 0,
      repairCalls: 0,
      pushResult: null,
    };
  }
  const pushResult = await Promise.resolve(dbPush({ staged, preflight, phase }));
  return {
    ok: true,
    staged,
    preflight,
    pushResult,
    dbPushCalls: 1,
    repairCalls: 0,
  };
}

function disposableIdentityOk(input) {
  if (input.disposableIdentityVerified === true) return true;
  if (input.disposableIdentityVerified === false) return false;
  const ref = input.projectRef || input.identity?.ref || input.identity?.id;
  const name = input.projectName || input.identity?.name;
  const org = input.orgId || input.identity?.organization_id || input.identity?.org;
  const host = input.host || input.identity?.host;
  if (!ref && !name && !org && !host && input.disposableIdentityVerified == null) {
    return false;
  }
  return (
    ref === APPROVED_DISPOSABLE_PROJECT_REF &&
    (name == null || name === APPROVED_DISPOSABLE_PROJECT_NAME) &&
    (org == null || org === APPROVED_DISPOSABLE_ORG_ID) &&
    (host == null || host === APPROVED_DISPOSABLE_HOST)
  );
}

function productionRejectedOk(input) {
  if (input.productionIdentityRejected === true) return true;
  if (input.productionIdentityRejected === false) return false;
  const ref = input.projectRef || input.identity?.ref || input.identity?.id;
  if (ref == null) return false;
  return ref !== PRODUCTION_REF;
}

export function evaluateRepairSafetyGate(input = {}) {
  const file = input.file;
  const version = input.targetVersion || PREASSIGNED_VERSIONS[file];
  const gates = [];
  const fail = (id, detail) => {
    gates.push({ id, ok: false, detail });
  };
  const pass = (id, detail) => {
    gates.push({ id, ok: true, detail: detail || true });
  };

  if (!F3_FORWARD_FILES.includes(file)) {
    fail("authorized_file", `unknown file ${file}`);
  } else {
    pass("authorized_file");
  }

  if (!disposableIdentityOk(input)) {
    fail("disposable_identity", "exact disposable identity not verified");
  } else {
    pass("disposable_identity");
  }

  if (!productionRejectedOk(input)) {
    fail("production_rejected", "production identity was not rejected");
  } else {
    pass("production_rejected");
  }

  if (input.cliVersion !== CLI_PIN) {
    fail("cli_pin", `cliVersion=${input.cliVersion} required=${CLI_PIN}`);
  } else {
    pass("cli_pin");
  }

  const intendedPrefix = F3_FORWARD_FILES.includes(file) ? authorizedStagedPrefixThrough(file) : null;
  const staged = Array.isArray(input.stagedMigrations) ? input.stagedMigrations : null;
  const prefixOk =
    intendedPrefix != null &&
    Array.isArray(staged) &&
    staged.length === intendedPrefix.length &&
    intendedPrefix.every((name, i) => staged[i] === name);
  if (!prefixOk) {
    fail("staged_prefix_complete", `staged=${JSON.stringify(staged)} intended=${JSON.stringify(intendedPrefix)}`);
  } else {
    pass("staged_prefix_complete");
  }

  const injectInstalled =
    input.injectInstalled === true ||
    Number(input.injectStatus) === 0 ||
    input.injectOk === true;
  const injectTargetsVersion =
    String(input.injectSql || "").includes(String(version)) &&
    String(input.injectSql || "").includes(HISTORY_INJECT_MARKER);
  if (!injectInstalled || (input.injectSql != null && !injectTargetsVersion)) {
    fail("inject_installed_exact_version", "failure injection not installed for exact target version");
  } else {
    pass("inject_installed_exact_version");
  }

  const nonzero = input.exitStatus !== 0 && input.exitStatus != null;
  if (!nonzero) fail("nonzero_exit", `exitStatus=${input.exitStatus}`);
  else pass("nonzero_exit");

  const output = textOf(input);
  if (!hasTargetSpecificInjectMarker(output, version)) {
    fail("target_inject_marker", "missing target-specific history-failure marker");
  } else {
    pass("target_inject_marker");
  }

  const probe = input.probe;
  const probeText = probe ? textOf(probe) : textOf({
    stdout: input.probeStdout,
    stderr: input.probeStderr,
    output: input.probeOutput,
  });
  const unrelated = unrelatedMigrationSqlErrors(output, version, probeText);
  if (unrelated.length > 0) {
    fail("no_unrelated_sql_error", unrelated[0]);
  } else {
    pass("no_unrelated_sql_error");
  }

  const rows = Array.isArray(input.historyRows) ? input.historyRows : [];
  const present = rows.some((row) => String(row?.version) === String(version));
  if (present) fail("target_history_absent", "target version unexpectedly present");
  else pass("target_history_absent");

  const probeResult = probe || (
    input.probeStatus != null || input.probeStdout != null || input.probeStderr != null
      ? { status: input.probeStatus, stdout: input.probeStdout, stderr: input.probeStderr, file }
      : null
  );
  const probeEval = evaluateObjectProbe(probeResult || {}, { file });
  const objectsOk = probeEval.present === true;
  if (!objectsOk) {
    fail("expected_objects", probeEval.reason || `objectsPresent=${input.objectsPresent}`);
  } else {
    pass("expected_objects");
  }
  if (input.securityPostconditionsOk === false || !objectsOk) {
    fail(
      "security_postconditions",
      objectsOk ? "security postconditions missing" : "objects missing so security postconditions not proven",
    );
  } else {
    pass("security_postconditions");
  }

  const calibration = evaluatePlatformAclCalibration({
    envelope: Object.prototype.hasOwnProperty.call(input, "platformAclEnvelope")
      ? input.platformAclEnvelope
      : SEALED_PLATFORM_ACL_ENVELOPE,
    targetObjectClass: input.platformAclTargetObjectClass,
  });
  if (!calibration.ok) {
    fail("platform_acl_calibration", calibration.reason || PLATFORM_ACL_CALIBRATION_HOLD);
    fail("fingerprint_exact", calibration.reason || PLATFORM_ACL_CALIBRATION_HOLD);
  } else {
    pass("platform_acl_calibration");
    const fp = fingerprintCompleteAndExact(input.fingerprint, file);
    if (!fp.ok) fail("fingerprint_exact", fp.reason);
    else pass("fingerprint_exact");
  }

  const authorized = FROZEN_DIGESTS[file];
  const digestOk =
    input.digest === authorized &&
    (input.onDiskDigest == null || input.onDiskDigest === authorized);
  if (!digestOk) fail("sql_digest", `digest ${input.digest} != ${authorized}`);
  else pass("sql_digest");

  const ok = gates.every((g) => g.ok);
  const originalError =
    unrelated[0] ||
    (hasTargetSpecificInjectMarker(output, version) ? null : extractSqlFailureLines(output)[0]) ||
    input.originalSqlError ||
    null;
  return {
    ok,
    repairAuthorized: ok,
    continuation: ok,
    gates,
    failedGates: gates.filter((g) => !g.ok).map((g) => g.id),
    hold: ok ? null : REPAIR_SAFETY_HOLD,
    originalSqlError: originalError,
    poisonCleanupOnly: !ok,
    nextMigration: ok,
    objectProbe: probeEval,
  };
}

async function invokeMaybeAsync(fn) {
  return await Promise.resolve(fn());
}

/**
 * Classify, then maybe repair. Cleanup always runs (finally-style).
 * Repair is invoked only when the gate authorizes AND cleanup exits 0
 * with no SQL error AND a separate probe proves poison is absent.
 * Optional teardown is recorded separately and never counted as cleanup success.
 */
export async function runRepairSafetyThenMaybeRepair({
  gateInput,
  cleanup,
  verifyPoisonAbsent,
  repair,
  teardown,
  dbPush,
  continuation: continuationFn,
  frozenTarget,
  frozenTargetResult,
} = {}) {
  const spies = {
    repairCalls: 0,
    dbPushCalls: 0,
    continuationCalls: 0,
    cleanupCalls: 0,
    verifyCalls: 0,
    historyMutated: false,
    usedFallbackParser: false,
    reconstructedPoisonObject: false,
  };
  const boundTarget = frozenTargetResult
    ? frozenTargetResult
    : frozenTarget
      ? assertFrozenTargetUnmutated(frozenTarget)
      : constructImmutableValidatedTargetFromConnection({ source: "repair-safety-connection" });
  const gate = evaluateRepairSafetyGate(gateInput);
  let cleanupResult = null;
  let cleanupError = null;
  let verifyResult = null;
  let verifyEval = { ok: false, absent: false, reason: "verify not run" };
  let repairResult = null;
  let repairAttempted = false;
  let teardownResult = null;
  let teardownRecorded = false;
  let dbPushResult = null;
  let continuationResult = null;

  const rejectBeforeRepair = !boundTarget.ok || !gate.ok;

  try {
    if (typeof cleanup === "function") {
      try {
        spies.cleanupCalls += 1;
        cleanupResult = await invokeMaybeAsync(cleanup);
      } catch (err) {
        cleanupError = err;
        cleanupResult = { threw: true, error: String(err?.message || err) };
      }
    } else {
      cleanupResult = { missing: true };
    }

    const cleanupProof = evaluateCleanupProven(cleanupResult);
    const cleanupOk = cleanupProof.ok === true && cleanupError == null;

    if (boundTarget.ok && gate.ok && cleanupOk && typeof verifyPoisonAbsent === "function") {
      try {
        spies.verifyCalls += 1;
        verifyResult = await invokeMaybeAsync(verifyPoisonAbsent);
        if (verifyResult?.reconstructed === true
          || verifyResult?.assembledFromExtractedFields === true
          || verifyResult?.stdoutIsReconstructed === true
          || verifyResult?.__assembled === true) {
          spies.reconstructedPoisonObject = true;
        }
        verifyEval = evaluatePoisonAbsent(verifyResult, { frozenTarget: boundTarget.target });
        spies.usedFallbackParser = verifyEval.usedFallbackParser === true;
        spies.reconstructedPoisonObject = spies.reconstructedPoisonObject
          || verifyEval.reconstructedPoisonObject === true;
      } catch (err) {
        verifyResult = { threw: true, error: String(err?.message || err) };
        verifyEval = { ok: false, absent: false, reason: "verify threw", error: String(err?.message || err) };
      }
    } else if (!boundTarget.ok) {
      verifyEval = {
        ok: false,
        absent: false,
        reason: boundTarget.reason || IMMUTABLE_TARGET_HOLD,
        parser_verdict: boundTarget.parser_verdict,
      };
    } else if (gate.ok && cleanupOk && typeof verifyPoisonAbsent !== "function") {
      verifyEval = { ok: false, absent: false, reason: "verifyPoisonAbsent callback missing" };
    } else if (gate.ok && !cleanupOk) {
      verifyEval = { ok: false, absent: false, reason: cleanupProof.reason || "cleanup not proven" };
    }

    const repairAllowed = Boolean(
      boundTarget.ok
      && gate.ok
      && cleanupOk
      && verifyEval.ok
      && verifyEval.absent === true
      && spies.reconstructedPoisonObject !== true
      && spies.usedFallbackParser !== true,
    );
    if (repairAllowed) {
      if (typeof repair !== "function") {
        throw new Error("HOLD: repair executor required after authorized gate");
      }
      repairAttempted = true;
      spies.repairCalls += 1;
      repairResult = await invokeMaybeAsync(repair);
    }
    const repairOk = !repairAttempted || (repairResult && repairResult.status === 0);
    if (repairAllowed && repairOk && typeof dbPush === "function") {
      spies.dbPushCalls += 1;
      dbPushResult = await invokeMaybeAsync(dbPush);
    }
    if (repairAllowed && repairOk && typeof continuationFn === "function") {
      spies.continuationCalls += 1;
      continuationResult = await invokeMaybeAsync(continuationFn);
    }
  } catch (err) {
    if (typeof teardown === "function" && !teardownRecorded) {
      try {
        teardownResult = await invokeMaybeAsync(teardown);
        teardownRecorded = true;
      } catch {
        /* teardown is never cleanup success */
      }
    }
    throw err;
  }

  if (typeof teardown === "function" && !teardownRecorded) {
    try {
      teardownResult = await invokeMaybeAsync(teardown);
      teardownRecorded = true;
    } catch (err) {
      teardownResult = { threw: true, error: String(err?.message || err) };
      teardownRecorded = true;
    }
  }

  const cleanupProof = evaluateCleanupProven(cleanupResult);
  const cleanupOk = cleanupProof.ok === true && cleanupError == null;
  const repairOk = !repairAttempted || (repairResult && repairResult.status === 0);
  const repairAuthorized = Boolean(
    boundTarget.ok
    && gate.ok
    && cleanupOk
    && verifyEval.ok
    && verifyEval.absent === true
    && spies.reconstructedPoisonObject !== true,
  );
  return {
    gate,
    repairAuthorized,
    gateAuthorized: gate.ok,
    repairAttempted,
    repair: repairResult,
    continuation: Boolean(repairAttempted && repairOk && repairAuthorized),
    nextMigration: Boolean(repairAttempted && repairOk && repairAuthorized),
    cleanup: cleanupResult,
    cleanupError: cleanupError ? String(cleanupError.message || cleanupError) : null,
    cleanupProven: evaluateCleanupProven(cleanupResult).ok === true && cleanupError == null,
    verify: verifyResult,
    poisonAbsent: verifyEval.absent === true,
    poisonVerify: verifyEval,
    teardown: teardownResult,
    teardownRecorded,
    poisonCleanupOnly: true,
    repairOk,
    frozenTarget: boundTarget.ok ? boundTarget.target : null,
    targetBinding: boundTarget,
    dbPush: dbPushResult,
    continuationResult,
    repairCalls: spies.repairCalls,
    dbPushCalls: spies.dbPushCalls,
    continuationCalls: spies.continuationCalls,
    cleanupCalls: spies.cleanupCalls,
    verifyCalls: spies.verifyCalls,
    historyMutated: spies.historyMutated,
    usedFallbackParser: spies.usedFallbackParser,
    reconstructedPoisonObject: spies.reconstructedPoisonObject,
    rejectBeforeRepair,
  };
}

/**
 * Production-path wrapper used by hosted qualify and harness E2E negatives.
 * Same functions: process-result contract, original stdout parser, exact
 * envelope validator, target-binding comparator, cleanup, poison-absence,
 * repair auth, repair / db-push / continuation callbacks.
 */
export async function runQualifyPoisonBoundPath(input = {}) {
  return runRepairSafetyThenMaybeRepair(input);
}
